    "descriptionEn": "Among the six pagodas in Phnom Penh that were built during the reign of King Ponhea Yat in 1437, only Wat Ounalom has traces of the Angkorian period. It was built during the 11th century in the Koh Ker style, according to research. This sandstone temple faces east and has a balcony on every corner. The temple has an additional roof and balcony, but from the inside we can still see the old stone structures. This temple was transformed into a stup during post-Angkorian era for worship in Buddhism called Prasat Po Loam, which is believed to be the burial place of the holiest relics, unna lom (eyebrows) of Preah Asajithe (ព្រះធក្សជិត្ថេរ), also known as Unalom stupa as well as the name of the pagoda. This temple is a single temple built of sandstone with laterite walls surrounded. From the outside, it looks like a new-built stupa, but from the inside, it is an old temple with wall-lined with large and thick sandstone. Unfortunately, tourists are not able to see the lintels and the inscription, except the rubble remains. The temple has a regular guard to take care of. The temple has a big horizontal wooden beam. It is believed that there is super power at the entrance of the stupa which can lead the monks to any mountains. When they want to meditate, they only enter this stupa and they will reveal themselves in the quiet forest or mountains.",
