    "descriptionEn": "Botum Vatey Pagoda, known as Wat Botum, was built by the King Ponhea Yat (1405-1467) in the 15th century, south of the Royal Palace. It is one among the other five aging pagoda in Phnom Penh which were built in the ancient time. This pagoda is also known as Lotus Pagoda since this place was a small highland surrounded by a pond full of lotus. The pagoda was named in 1865. The magnificent construction seen today was built in 1937. In the area of the pagoda, there are many stupas in which one of them is the one for keeping the remains of the Kings. The huge yellow and green statue at the pagoda gates represent the Naga, the serpent in ancient myths. The pagoda has been proposed to be a tourism site in Phnom Penh.",
