    "nameKh": "វត្តសារាវ័នតេជោ",
    "nameEn": "Sara Voan Techo Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តសារាវ័នតេជោ សព្វថៃ្ងនេះកាលពីដំបូងឡើយគឺជាទីព្រៃលិចទឹកមួយឈ្មោះថា \"បឹងរាំង\" មានទួលមួយដែលមានដើមរាំងភ្នំ និងដើមរាំងទឹកដុះមីរដេរដាសទ្រប់ទ្រុល។ នៅសម័យលោកយាយពេញ គេនិយម មគធៈភាសា និងសំស្រឹ្កត ហេតុដូចេ្នះហើយទើបគេ ហៅទីទួលនោះជាភាសាបាលីថា ទួលសាលវ័ន។ ក្រោយមកនាឆ្នាំ ១៤២២ ទើបទីនេះកកើតជាវត្ត ហើយបន្ថែមនាម ឧកញ៉ាតេជោ ស្រី ជាចៅហ្វាយខេត្ត សំរោងទង ដែលបានកេណ្ឌប្រជានុរាស្រ្តឲ្យមកជីកយកអាចម៍ដីតាមទីវាលទំនាប ក្លាយជាបឹង ឈ្មោះថា«បឹងឧកញ៉ាតេជោ»។ ព្រះវិហាររបស់ទីអារាម\"សារាវ័នតេជោ\"ត្រូវបានកសាងឡើងនៅឆ្នាំ១៨៩២ ហើយបាន ធ្វើការជួសជុលធំម្ដង កាលពីអំឡុងឆ្នាំ១៩៥២ ក៏ប៉ុនែ្តនៅរក្សារចនាប័ទដើមទាំងអស់គ្មានការផ្លាស់ប្ដូរ នោះទេ។",
    "descriptionEn": "The location of Sara Voan Techo pagoda used to be a flooded forest called “Boeung Raing”. The so-called name existed since there was a hill with a cannonball tree and bushed of freshwater mangroves in this flooded area. During the era of Yeay Penh, Meak Keak Theak language and Sanskrit were popularly used; thus, this high hill was called “Tourl Sara Voan”. Later, in 1422, the pagoda was established by adding the name of Oknha Techo Sri, Somrong Tong Provincial Chief, who mobilized people to dig and take out the soil from the lowland. This place later became a pond, known as “Boeung Oknha Techo”. The Buddhist temple of the “Sara Voan Techo Pagoda” was built in 1892, and was repaired in 1952 by keeping the original styles.",
