    "descriptionKh": "សារមន្ទីរព្រះស្រីឦសានវរ្ម័នឬសារមន្ទីរសេដ្ឋកិច្ចនិងរូបិយវត្ថុនៃកម្ពុជា ជាសារមន្ទីរដ៏ទំនើបមួយដែលបានបើកដំណើរការឆ្នាំ ២០១៩។ សារមន្ទីរបង្ហាញអំពីសាវតាសេដ្ឋកិច្ច និងរូបិយវត្ថុរបស់ខ្មែរតាំងពីសម័យកាលហ្វូណន រហូតមកដល់បច្ចុប្បន្ន ដែលកូនខ្មែរគ្រប់រូបគួរតែទៅទស្សនា យ៉ាងហោចណាស់បានរំលឹកឡើងវិញនូវអ្វីដែលយើងធ្លាប់ដឹង និងអ្វីដែលយើងមិនធ្លាប់ដឹងអំពីប្រវត្តិសាស្រ្ត ។",
    "descriptionEn": "Preah Srei Isan Varman Museum or the museum of economy and currency of Cambodia is a modern museum opened to public in 2019. The museum presents the history of the Cambodian economy and currency from the Funan period to the present, which every Cambodian child should visit, at least reminiscent of what we have or haven not known about history.",
