    "categoryKh": "កោះ & ឆ្នេរសមុទ្រ",
    "categoryEn": "Islands & Beaches",
    "descriptionKh": "រមណីយដ្ឋានធម្មជាតិនៃរាជធានីភ្នំពេញ បន្ទាប់ពីការកាត់បញ្ចូលសង្កាត់នេះ ទៅក្នុងរាជធានី ដែលពីមុននៅក្នុងស្រុកមុខកំពូលខេត្តកណ្ដាល។ ទីនោះជាភូមិតម្បាញសូត្រ បែបបុរាណដែលសិប្បករ ក្នុងតំបន់មានជំនាញរវៃ និងត្បាញសម្រាប់ជីវភាពពួកគេ និងជាភូមិនេសាទផងដែរ។ ភ្ញៀវទេសចរអាចរីករាយជាមួយជំនាញក្នុងការត្បាញ និងនេសាទរបស់ពួកគេ។ កោះដាច់ មានបណ្ដោយ១២ គីឡូម៉ែត្រ និងទទឹងពី១០០ម៉ែត្រដល់២៥០០ម៉ែត្រ ព័ទ្ធជុំវិញដោយទន្លេមេគង្គ ដូចនេះទើបមានរមណីយដ្ឋានធម្មជាតិ ប្រកបដោយឆ្នេរខ្សាច់ស្រស់ស្អាតនៅផ្នែកក្បាលកោះ មានកន្លែងងូតទឹកកម្សាន្ត ដែលគេធ្វើជារោងតូចៗ។ នៅពេលព្រឹកទឹកទន្លេកម្ពស់ត្រឹមលិចខ្នងជើង តែនៅពេលថ្ងៃត្រង់ អាចឡើងដល់ត្រឹមជង្គង់ទៅតាមទំនាញរបស់ព្រះអាទិត្យ។",
    "descriptionEn": "This resort has become one of the natural resorts of the Phom Penh city following the inclusion of this Sangkat into the territory of the capital city which before it was in Muk Kompul district, Kandal province. It is a traditional silk weaving village where local artisans specialize in weaving for their profession and livelihood, adding up to another profession, fishing. Tourists usually eye-catch with the very skillful of the villagers’ weaving and fishing. Koh Dach is 12 kilometers long and 100 meters to 2,500 meters wide, surrounded by the Mekong River, so there is a natural beach with a beautiful beach at the head of the island with some small natural bath pools. In the morning, the river rises to the feet-level, but at noon it rises to the knee-level by the gravity of the sun.",
