    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "រមណីយដ្ឋានមួយដែលមានលក្ខណៈខុសពីគេ គឺជាតូបបណ្ដែតលើទឹក ដែលទទួលបានការពេញនិយមពីអ្នកនៅទីក្រុងភ្នំពេញ ជាពិសេសយុវវ័យ។ មូលហេតុងាយយល់ដោយសារវាស្ថិតនៅជិតទីក្រុងអាចទៅមកងាយស្រួលដោយម៉ូតូ។ នៅទីនេះមានបម្រើសេវាម្ហូបអាហារដ៏ឈ្ងុយឆ្ងាញ់ និងមានតូបបណ្ដែតលើទឹកដោយយកធុងដែក ឬជ័រជាពោងតម្រៀបជាប់គា្នចងភ្ជាប់ដោយខ្សែពួរ ទៅត្រើយសងខាងនៃស្ទឹងព្រែកត្នោត។ ពេលទឹកស្ទឹងឡើងជន់ជោរខ្លាំងនារដូវវស្សា ម្ចាស់តូបអូសមកចងទុក លុះដល់ផុតរដូវវស្សាទើបគេទម្លាក់មកវិញ។",
    "descriptionEn": "A floating kiosk resort is amazing and interesting among young people from Phnom Penh and the surrounding. The resort is close enough to the city and convenient to travel to by motors. Tourists are served with drink and delicious food. The kiosks are made of steel or plastic buckets arranged in a row, tied with ropes to both sides of Steung Prek Tnaot. When the river rises and floods during the rainy season, the owner of the kiosks drags them away and does not return until after the rainy season.",
