    "id": "rac-k01019",
    "nameKh": "ពហុកីឡដ្ឋានមរតកតេជោ",
    "nameEn": "Morodok Decho stadium",
    "categorySlug": "nature",
    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ពហុកីឡដ្ឋាននេះជាជំនួយឥតសំណងរបស់សាធារណរដ្ឋប្រជាមានិតចិន សាងសង់ឡើងលើផ្ទៃដី១៦ហិកតា។ រចនាសម្ព័នពហុកីឡដ្ឋានជាតិមរតកតេជោ មានការធ្វើកីឡដ្ឋានរាងជាសំពៅគឺដើម្បីរំលឹកដល់ទំនាក់ទំនងដែលកន្លងមកកម្ពុជាមានជាមួយ ចិនជាយូរមកហើយ គឺតាំងពីសម័យធ្វើដំណើរដោយសំពៅម្ល៉េះ។ ការសាងសង់ពហុកីឡាដ្ឋានបានបានចាប់ផ្ដើមនៅឆ្នាំ២០១៧ ហើយបញ្ចប់គម្រោងសាងសង់នៅឆ្នាំ២០២១។ រដ្ឋាភិបាលចិនបានផ្ដល់ជំនួយចំនួន ១.១ ពាន់លានយន់ចិន (ប្រហែល ១៦០ លានដុល្លារ) សម្រាប់ការសាងសង់កីឡដ្ឋានដែលត្រូវបានអភិវឌ្ឍដោយ សាជីវកម្មវិស្វកម្មសំណង់រដ្ឋចិន ។ វិស្វករចិនប្រមាណ៣៤០នាក់ និងកម្មករនិងអ្នកបច្ចេកទេសកម្ពុជា២៤០នាក់បានចូលរួមក្នុងការសាងសង់នេះ។ ទីលានបាល់ទាត់ មានដំបូលគ្របបិទបើកបាន អាចផ្ទុកអ្នកទស្សនារហូតដល់ទៅ ៦ម៉ឺននាក់។ ទីលានបាល់ទាត់ត្រូវបានដាំស្មៅស្របតាមស្តង់ដារបស់ FIFA ហើយដែលពហុកីឡដ្ឋាននេះនឹងត្រូវបានប្រើប្រាស់ សម្រាប់ការប្រកួតកីឡា SEAGAME 2023 លើកទី ៣២ និង ASEAN Para Games លើកទី ១២ ដែលកម្ពុជាធ្វើជាម្ចាស់ផ្ទះ។",
    "descriptionEn": "The stadium is a 16-hectare grant from the People's Republic of China. The structure of the Moradok Techo National Stadium has a ship-shaped stadium to commemorate Cambodia's long-standing relationship with China, dating back to the days when ships sailed. Construction of the stadium began in 2017 and was completed in 2021. The Chinese government has provided 1.1 billion yuan (about $ 160 million) in aid for the construction of the stadium, which was developed by the Chinese State Civil Engineering Corporation. About 340 Chinese engineers and 240 Cambodian workers and technicians participated in the construction. The covered football field can accommodate up to 60,000 spectators. The football field is planted according to FIFA standards and the stadium will be used for the 32nd SEAGAME 2023 and the 12th ASEAN Para Games, which Cambodia is hosting.",
    "photoUrl": "https://raw.githubusercontent.com/igpubinfo-max/Khmer-Food-Tourism/8d322f9/public/destinations/rac-k01019.jpg",
    "provinceKh": "រាជធានីភ្នំពេញ",
