    "categorySlug": "nature",
    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "មាត់ទន្លេជាកន្លែងដែលគួរឲ្យចាប់អារម្មណ៍មួយនៅក្នុងទីក្រុងរួមមាន ព្រះបរមរាជវាំង វិចិត្រសាល តៀម ភោជនីយដ្ឋាន និងហាងដែលស្ថិតនៅតាមបណ្ដោយម្ខាងនៃតិរវិថីព្រះស៊ីសុវត្ថិ ដែលអាចគយគន់ទន្លេចតុមុខ ទន្លេសាប ទន្លេមេគង្គ និងទន្លេបាសាក់។ នៅពេលទស្សនាកម្ពុជា អ្នកទេសចរអាចធ្វើដំណើរតាមដងទន្លេមេគង្គនិងគយគន់ទេសភាពដ៏ត្រកាលតាមបណ្ដោយច្រាំងទន្លេនេះ។ មានសហគមន៍ជាច្រើន រស់នៅប៉ប្រះនឹងមាត់ទន្លេអស់រយៈពេលជាច្រើនសតវត្សរ៍កន្លងមកហើយ។ អ្នកទេសចរអាចអង្គុយលើដំបូលយានដើម្បីទទួលទានទឹកតែដ៏ឆ្ងាញ់ពិសា ទស្សនាភូមិតូចៗនៅតាមបណ្ដោយច្រាំងទន្លេ គយគន់ប្រាសាទដែលអើតលឹមៗពីចម្ងាយ និងស្រូបយកខ្យល់អាកាសដ៏បរិសុទ្ធ នៅកណ្ដាលទន្លេធម្មជាតិនេះ។ ជួនកាលដំណើរកម្សាន្តតាមទន្លេនេះអាចបញ្ជារៀបចំជាពិធីតូចៗក្នុងគ្រួសារដូចជាការជួបជុំមិត្តភក្ដិ ឬបុណ្យខួបកំណើតជាដើមបានផងដែរ។",
    "descriptionEn": "The riverfront is one of the most interesting places in the city, including the Royal Palace, galleries, restaurants and shops located along the side of Sisowath Quay, which overlooks the Chaktomuk, Tonle Sap, Mekong and Bassac rivers. When visiting Cambodia, tourists can travel along the Mekong River and admire the spectacular scenery along the riverbank. Many communities have been living along the river for centuries. Visitors can sit on the roof of the tourist boat for a cup of delicious tea, visit small villages along the banks of the river, admire the temples from the distance and breathe the fresh air from the middle of this natural river. With the boat excursion, tourists can ask for special services as small event preparation, family and friend gathering or birthday celebration and so on.",
