    "descriptionKh": "ផ្សាររាត្រីនៅទីក្រុងភ្នំពេញស្ថិតនៅខាងមុខផ្សារចាស់នៅក្បែរមាត់ទន្លេ និងជារឿយៗមានភ្ញៀវទេសចរជាច្រើនទៅទីនោះដើម្បីទិញឥវ៉ាន់ផ្សេងៗ។ បច្ចុប្បន្នមានស្តង់ជាង១៥០ បើកលក់ទំនិញផ្សេងៗចាប់ពីសម្លៀកបំពាក់ គ្រឿងតុបតែងកាយ រហូតដល់គ្រឿងសង្ហារឹមនិងវត្ថុអនុស្សាវរីយ៍ជាដើម។ ការបង្កើតឲ្យមានផ្សាររាត្រីនៅទីក្រុងភ្នំពេញ ជាការផ្ដល់ជូនដល់ភ្ញៀវទេសចរក្នុងស្រុកនិងក្រៅស្រុកនូវកន្លែងសម្រាប់ទិញវត្ថុអនុស្សាវរីយ៍ត្រឡប់ទៅផ្ទះវិញ។ ទីនេះគឺជាទីកម្សាន្តសម្រាប់ទេសចរណ៍ដែលចង់ដើរកម្ស្នាន្តនៅពេលរាត្រី ដែលនៅទីនោះផងដែរក៏ជាចំណតរថយន្តក្រុង និងចំណតរថយន្តពេលយប់ជាច្រើន ដែលចេញដំណើរទៅកាន់ទីរួមខេត្តផ្សេងៗ ជាបន្តបន្ទាប់ផងដែរ។",
    "descriptionEn": "The night market in Phnom Penh is in front of the Old Market near the river and often many tourists go there to shop. Currently, there are more than 150 booths selling everything from clothes, accessories to furniture and souvenirs. The establishment of a night market in Phnom Penh provides local and foreign tourists with a place to buy souvenirs to take home. This is a place for tourists who want to go for a night out, as well as a bus stop and many car-parked at night which that travel different provincial towns.",
