    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "វិមានឈ្នះឈ្នះត្រូវបានសម្ពោធនៅចុងខែធ្នូឆ្នាំ២០១៨ ដែលវិមានលើទំហំដី៨ហិកតានេះសង់ដើម្បីរំឭកដល់ការធ្វើសមាហរណកម្មកងទ័ពខ្មែរក្រហមកាលពីឆ្នាំ១៩៩៨ដែលនាំមកនូវសន្តិភាពពេញលេញ ដល់កម្ពុជា។ វិមានមានកម្ពស់ ៥៤ ម៉ែត្រតួផ្ទៃរាងការ៉េមានជ្រុងប្រវែង ១១៧ម៉ែត្រ។ តួខាងក្រោមមានជ្រុងចំនួន ៥ តំណាងឲ្យយុទ្ធសាស្ត្រចំនួន៥ ចំណុចរួមមាន បំបែក ឯកោ បញ្ចប់ ធ្វើសមាហរណកម្ម និងអភិវឌ្ឍ។ ចំណែកកំពូលដែលមានកម្ពស់ ៣៣ ម៉ែត្រខាងលើតំណាងឲ្យការធានាចំនួន៣ គឺ ទី ១ ការធានារូបកាយ និងអាយុជីវិត ទី ២ ការធានាអាជីព និងមុខរបរ និងទី ៣ ការធានាកម្មសិទ្ធិទាំងចលនទ្រព្យ និងអចលនទ្រព្យ។ ក្រោយសមាហរណកម្ម កម្ពុជាមានយុទ្ធសាស្ត្រពីរ គឺទីមួយប្រែក្លាយតំបន់អតីតសមរភូមិឲ្យទៅជាទីផ្សារនិងតំបន់អភិវឌ្ឍន៍ និងទីពីរ ប្រែក្លាយតំបន់ព្រំដែនទៅជាតំបន់ជាប់ប្រទេសជិតខាងឲ្យទៅជាព្រំដែនសន្តិភាព មិត្តភាព សហប្រតិបត្តិការ និងការអភិវឌ្ឍ។ វិមានឈ្នះ-ឈ្នះ មានឆ្លាក់រូបនៅតាមជញ្ជាំងជុំវិញបរិវេណដែលបរិយាយអំពីដំណើរឆ្ពោះទៅរកការផ្ដូលរំលំរបបខ្មែរក្រហមនិងរូបដែលឆ្លុះបញ្ចាំងពីការអភិវឌ្ឍរបស់ប្រទេសកម្ពុជាក្នុងសម័យថ្មីផងដែរ។",
    "descriptionEn": "Win-Win Memorial was inaugurated at the end of December 2018. The eight-hectare area of land memorial was built to commemorate the integration of the Khmer Rouge army in 1998, which led Cambodia to a complete peace. The memorial is 54 meters high; the main structure is in square-shape with corners of 117 meters. The bottom five corners represent five strategies: breaking up, isolation, completion, integration, and development. The 33-meter-high top represents three guarantees: physical and life insurance, career and occupation insurance, and property and real estate insurance. After the integration, Cambodia has two strategies: first, to turn the former battlefield into a market and development area, and second, to turn the border area with neighboring countries into a border of peace, friendship, cooperation and development. Around the base of Win-Win Memorial, are series of carving that depict various scenes and events about the journey of defeating Khmer Rouge and the development of modern Cambodia.",
