    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "សួនទឹកស៊ីន្នីស្ថិតនៅក្នុងប្រភេទរមណីយដ្ឋានទេសចរណ៍កែច្នៃ ដែលអាចធ្វើអោយភ្ញៀវទេសចរណ៍ មានចំណាប់អារម្មណ៍ រួមមាន៖ ការលេងទឹកឬហែលទឹក, ជិះក្ដាររំអិល, ទស្សនាសួនដាំណាំ, អាងហែលទឹក និងចំណុចផ្សេងៗទៀត។ លោកអ្នកអាចរីករាយថ្ងៃចុងសប្ដាហ៍ជាមួយគ្រួសារនៅ សួនទឹក ស៊ីន្នី ដោយនៅសួនទឹកនេះមាន អាងហែលទឹកសំរាប់កុមារតូចៗ ហើយសំរាប់មនុស្សធំមានចិញ្ចឹមសត្វជាច្រើនប្រភេទនិងអាងចិញ្ចឹមត្រីច្រើនបែបផងដែរ។ សួនមានទទួលរៀបចំពិធីផ្សេងៗ មានចំណតរថយន្តធំទូលាយ មានតូបជាច្រើន សម្រាប់បរិភាគអាហារ និងមានបំរើសេវាកម្ម ម្ហូបអាហារផងដែរ។",
    "descriptionEn": "Sinny water park is a kind of man-made water park which attracts tourists with many different kinds of activities: swimming, skiing board, visiting vegetable farms, big swimming pool for adults and kids, many kinds of feeding-animals, and fish ponds. The great time to visit shall be on weekend. This place is available for the service of events since it has convenient parking lots for big vans, many food kiosks, and food services.",
