    "nameEn": "Stupa of Champus Ka’ek Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "រណ្ដៅសាកសពជាច្រើននៅក្នុងវត្តចំពុះក្អែក ត្រូវបានគាស់កាលពីអំឡុងឆ្នាំ១៩៨០ ហើយឆ្អឹងលលាដ៏ក្បាល និងឆ្អឹងអវៈយវៈរាប់ពាន់ដែលគាស់បាន ត្រូវប្រជាជនជញ្ជូនយកទៅដាក់នៅបូជនីយដ្ឋាន មួយកន្លែងស្ថិតនៅក្នុងបរិវេណវត្ត។ មានខ្នោះឃ្នាងជាច្រើន បានត្រូវដាក់ព្យួរតាមរបាជញ្ជាំងដែលធ្វើ ពីលួសសំណាញ់ពទ្ធ័ជុំវិញអដ្ឋិធាតុ។ នរណាក៏អាចមើលឃើញអដ្ឋិធាតុរាប់ពាន់នេះយ៉ាងច្បាស់ដែរ។ ទីនេះក៏បានក្លាយជាកន្លែងប្រារឰថ្ងៃចងកំហឹងចំពោះបនប្រល័យពូជសាសនប៉ុលពត នៅរៀងរាល់ឆ្នាំនាថ្ងៃទី២០ ខែឧសភា។",
    "descriptionEn": "Many graves in Champus Ka’ek pagoda were excavated during the 1980s, and thousands of skulls and limbs were unearthed and transported to a monument inside the pagoda. Many shackles were hung on the wall bars made of wire mesh around the remains. Anyone can clearly see these thousands of remains. This place also became a place to celebrate the day of remembrance for the Pol Pot genocidal regime every year on May 20.",
