    "descriptionKh": "វត្តស្ងួនពេជ្រ ជាទីតាំងសម្លាប់ និងមន្ទីរសន្តិសុខរបស់ខ្មែរក្រហម។ នៅក្រោយឆ្នាំ១៩៧៩ ឆ្អឹងលលាដ៏ក្បាល និងឆ្អឹងអវៈយវៈមួយចំនួន ត្រូវបានរើសយកមកដាក់តម្កល់នៅក្នុងមន្ទីរបូជនីយដ្ឋានមួយក្នុងបរិវេណវត្តនេះ។ តាមសម្ដីរបស់ សាក្សី បានឱ្យដឹងថា ឆ្អឹងដែលដាក់ តម្កល់នេះ គឺត្រូវប្រជាជនយកមកពីទីតាំងសម្លាប់ក្បែរៗវត្ត។ តាមរបាយការណ៍របស់ ក្រុមស្រាវជ្រាវ ផែនទីរណ្ដៅសាកសពជំនាន់ខ្មែរក្រហមបានបញ្ជាក់ថា ទីនេះមានអដ្ឋិធាតុតិចតួច ប៉ុន្តែនៅតែមានការកសាងមន្ទីរបូជនីយដ្ឋានថ្មីរួចហើយ។",
    "descriptionEn": "Sgnourn Pich Pagoda was a killing site and a security center in Khmer Rouge regime. After 1979, a large number of skulls and limbs were collected and placed in a shrine in the pagoda area. Witnesses said skeletons kept in this shrine were collected from the killing sites nearby the pagoda. According the reports of a research team about maps and corpse pits, a new shrine will not be built because there are not many remains kept in.",
