    "descriptionKh": "មន្ទីរបូជនីយដ្ឋាននៅវត្តអង្គសេរីសួស្ដី ធ្លាប់បានដាក់តម្កល់អដ្ឋិធាតុយ៉ាងច្រើន ដែលត្រូវបានគាស់ចេញពីទីតាំងសម្លាប់នៅជ្រលងត្រើង ដែលស្ថិតនៅតាមដងផ្លូវពីព្រែកព្នៅទៅកាន់ភ្នំ ប្រសិទ្ធិត្រៃត្រឹង្គ។ ប៉ុន្តែសព្វថ្ងៃនេះ យើងឃើញនៅសល់តិចតួចបំផុត។ សាក្សីជាច្រើនដែលជាអ្នកធ្លាប់ចូល រួមគាស់រណ្ដៅសាកសពនៅប្រឡាយតាប៉ិ និងនៅជ្រលងត្រើយដោយផ្ទាល់ និងជាអ្នកដែលជញ្ជូនឆ្អឹងសាកសពតាមរទេះមកដាក់នៅក្នុងបូជនីយដ្ឋានវត្តអង្គសេរីសួស្ដី។ គោលបំណងនៃការគាស់រណ្ដៅសាកសព របស់ពួកគាត់ គឺដើម្បីរកមាស និងវត្ថុមានតម្លៃផេ្សងទៀតចេញពីរាងកាយសាកសព។ សាក្សីម្នាក់ទទួលស្គាល់ថា គាត់ជាអ្នកចុះទៅស្រង់ឆ្អឹងចេញពីលូទឹកនៃជ្រលងត្រើងដើម្បីរក មាស ហើយប្រាប់ថា «ឪពុកខ្ញុំស្រង់បានប្រហែល៥០លលាដ៏ក្បាលប៉ុណ្ណោះពីក្នុងជ្រលងនេះ នឹងនៅមានច្រើនទៀតដែលមិនបានស្រង់»។ ការគាស់រណ្ដៅសាកសពទាំងពីរកន្លែងនេះ គឺធ្វើឡើងនៅក្នុងឆ្នាំ១៩៨៣។ អដ្ឋិធាតុទាំងអស់ត្រូវនាំយកទៅដាក់នៅវត្តអង្គសេរីសួស្ដី។ សាក្សីម្នាក់ទៀត បានចូលរួមដឹកឆ្អឹង តាមរទេះក្របីមកដាក់នៅវត្តអង្គសេរីសួស្ដីដែរ ដែលគាត់ដឹកតែមួយរទេះទេ ហើយរទេះរបស់គាត់ផ្ទុកបានត្រឹមតែ១៥០ទៅ២០០លលាដ៏ក្បាលប៉ុណ្ណោះ។",
    "descriptionEn": "The shrine of Ang Serey Sour Sdey Pagoda is a place for a large number of remains excavated from the killing site in the Treung Valley, located on the road from Prek Pnov to Phnom Prasit Trai Treung. Many witnesses participated in the excavation in Ta Pek canal and Treung Valley and carried the skeletons by cow carts to the shrine of Ang Serei Sour Sdey pagoda. The aim of excavating the graves is to seek for gold and other valuable things attached to the corpses. A witness admitted that he is the one who carried the bones from the gorge to seek for gold. He added that his father recovered about 50 skulls from the valley, and there were many more uncounted for. The excavation of the two graves was in 1983. All of the remains were kept in Ang Serei Sour Sdey pagoda. Another witness said that he also participated in carrying the bones by buffalo-carts which one cart could carry about 150 to 200 skulls to Ang Serei Sour Sdey pagoda.",
