    "descriptionKh": "នៅលើកំពូលមួយនៃភ្នំឧដុង្គ មានប្រាសាទបុរាណមួយ ដែលខ្លោងទ្វារប្រាសាទត្រូវបានប្រើជាចំណែក មួយនៃព្រះវិហារអដ្ឋរស្ស គឺជាវិហារមួយបែរមុខឆ្ពោះទៅទិសខាងជើងទៅវិញ។ ខ្លោងទ្វារនេះ មាននៅសល់ផ្ដែរនិងសសរពេជ្រ ដែលគបានជួសជុលឡើងវិញ ជាច្រើនដង។ នៅក្នុងព្រះវិហារនេះ មានព្រះពុទ្ធបដិមាកម្ពស់ ១៨ ហត្ថ។ បច្ចុប្បន្នព្រះវិហារនេះ នៅសល់តែសរសរធំៗ រីឯដំបូលវិញ ត្រូវបានបំផ្លាញនៅក្នុងសម័យខ្មែរក្រហម ហើយត្រូវបានជួសជុលកសាងឡើងវិញ។ តាមរឿងនិទាន ព្រះរាជាប្រទេសចិនបានចាត់បេសកជនដើរស៊ើបសួរ ដើម្បីដឹងថាតើប្រទេសណាមានអារ្យធម៌ដូចម្ដេចខ្លះ? កាលនោះក្រុមបេសកជនចិនរកឃើញថា ប្រទេសខ្មែរមុខជាជួបប្រទះនូវសេចក្ដីថ្កុំថ្កើងរុងរឿងអស្ចារ្យហើយភ្នំព្រះរាជទ្រព្យជាទីឱ្យផលល្អដល់ប្រទេសដោយមានរាងដូចសត្វមករ គឺខ្លួនមករនៅត្រង់ព្រះចេតិយត្រៃត្រិង្ស ក្បាលនឹងពុកមាត់មករនៅត្រង់ព្រះចេតិយទន្ទឹម កន្ទុយមករនៅត្រង់ព្រះពុទ្ធរូបចូលនិព្វាន មិនតែប៉ុណ្ណោះនៅលើកំពូលភ្នំនោះ ថែមទាំងមានរូងមួយជ្រៅស្រឡូងទៅក្រោមផង ដែលពួកចិនយល់ឃើញថាជារូងសត្វមករ។ ដូច្នេះដើម្បីសេចក្ដីសុខដល់ប្រទេសចិនទៅអនាគត ពួកចិនចង់សន្ធប់រូងភ្នំនោះឲ្យជិត គឺមានតែមកសុំធ្វើវិហារនៅលើកំពូលភ្នំព្រះរាជទ្រព្យ ដែលក្នុងវិហារនោះ មានព្រះពុទ្ធរូបមារវិជ័យ ១ ព្រះអង្គអស្ចារ្យ កម្ពស់ ១៨ ហត្ថ ក៏ហៅថា \" វិហារអដ្ឋរស្ស \" ប្រែថា \" វិហារព្រះ ១៨ ហត្ថ \"។ ព្រះវិហារអដ្ឋរស្សត្រូវបានជួសជុលជាច្រើនលើក គឺក្នុងរជ្ជកាលព្រះចន្ទរាជា និង ព្រះនរោត្តម ព្រះស៊ីសុវត្ថិ ដោយមានសម្ដេចព្រះមហាសង្ឃរាជ ទៀង កាន់កាប់ការផ្ទាល់ ក្នុងគ.ស. ១៩១១។",
    "descriptionEn": "On one of the tops of Udong Mountain, there is an ancient temple where the gate of the temple is used as part of the Ethareus Temple, a temple facing north. The gate still has lintels and colonette that have been refurbished many times. Inside this temple, there is an 18-foot-tall Buddha statue. Today, only large pillars remain, and the roof was destroyed during the Khmer Rouge era but it was reconstructed. According to legend, the Chinese emperor sent missionaries to investigate which country was civilized. At that time, the Chinese missionaries found that Cambodia would experience great prosperity and Phnom Preah Reach Troap was a good place for the country, with the shape of a giant dragon, which its body was at the Trai Treung Stupa, its head and mustache was at Ton Tem Stupa, and its tail was the Preah Ang Chol Nipean Statue. Besides, there was also a cave deep down, which the Chinese consider to be the cave of the dragon. For the safety of China in the future, Chinese planned to close the cave by trickly asked to build a big temple on the top of Phnom Preah Reach Troap which there was an 18-cubit Buddha statue of Mea Vichey. Later, it was called Ethareus Temple meaning 18-cubit temple. Preah Vihear Ethareus was renovated many times during the reigns of Preah Chan Reachea and Norodom Preah Sisowath, and directly in charge by the supreme patriarch (Samdech Preah Moha Sangkha Reach) Tieng in 1911.",
