    "descriptionKh": "ក្នុងទីវត្តនេះ មានប្រាសាទសង់ពីថ្មបាយក្រៀម ដែលមានប្រាង្គបីរត់ជួរជើងត្បូងបែរមុខទៅកើត ប្រកបដោយទ្វារ បញ្ឆោតគ្រប់ទិសក្នុងប្រាង្គនីមួយៗ និងមានទ្វារពិតដែលមានស៊ុមជាថ្មភក់។ ក្នុងចំណោមប្រាង្គទាំងបី មានប្រាង្គមួយ សង់ពីឥដ្ឋ ដែលបាក់បែករលំអស់ នៅសល់តែមេទ្វារបញ្ឈរ។ ផ្ដែរទាំងអស់មានបាក់បែកខ្លះ ដែលមានចម្លាក់ស្ថិតក្នុងរចនាបថព្រៃក្មេង ស្ដីពីការកូរសមុទ្រទឹកដោះ រូបមនុស្សអង្គុយ និងព្រះឥន្ទ្រជិះលើដំរីក្បាលបី ។ ប្រាសាទមានសសរពេជ្រ រាងប្រាំបីជ្រុង នៅក្នុងប្រាសាទដែលរលំហើយ មានសង់លិង្គថ្មីមួយតម្កល់នៅទីនោះ។ ប្រាសាទនេះ ស្ថិតនៅជ្រុងខាងលិច ចន្លោះព្រះវិហារចាស់និងព្រះវិហារថ្មី ដែលទើបសាងសង់។ គួរកត់សម្គាល់ថា អាយុកាលរបស់ព្រះវិហារចាស់នេះក៏មានក្បែរឬលើសពី១០០ឆ្នាំដែរ។",
    "descriptionEn": "In this pagoda, there is a temple made of laterite with three towers running in a row facing south, with false doors in all directions in each tower and a real door with a sandstone frame. Among the three towers, one was made of bricks, but they were all broken, leaving only the jambs stand. There are some ruins and sculptures in the style of Prey Kmeng about the churning of the ocean of milk, a sitting person and Indra riding on a three-headed elephant. The temple has an octagonal colonettes in the collapsed temple and a new Linga hold there. This temple is located in the west corner between the old temple and the newly built temple. It should be noted that the old temple is more than 100 years old.",
