    "descriptionKh": "ភ្នំប្រសិទ្ធ មានពីរនៅទន្ទឹមគ្នាខ័ណ្ឌដោយជ្រលង បែងចែករវាងស្រុកអង្គស្នួល និងស្រុកពញាឮ។ ភ្នំខាងត្បូងពុំសូវមានសំណល់ប្រវត្តិសាស្ត្រទេ។ ចំណែកឯភ្នំខាងជើងវិញ មានប្រវត្តិសាស្ត្រ និងសំណល់បុរាណជាច្រើន ដូចជារូបសំណាកព្រះចូលនិពាន្តមួយយ៉ាងធំ ហើយក៏មាននៅសល់ប្រាសាទបុរាណមួយមុនសម័យអង្គរផងដែរ។ ប្រាសាទសង់ពីឥដ្ឋ បែកបាក់កំពូលអស់ មានសសរពេជ្រនិងផ្ដែរធ្វើពីថ្មភក់។ ប្រាសាទដែលមានវ័យចំណាស់ជាងគេក្នុងតំបន់នេះសង់នាសម័យចេនឡា មានឈ្មោះថា ប្រាសាទស្រីគ្រប់លក្ខណ៍។ ប្រាសាទមានក្បាច់រចនាល្អប្រណិត ថ្វីត្បិតតែត្រូវរបេះជ្រុះ ឬរលុបសឹងទាំងអស់ក៏ដោយ។ ប្រាសាទបែរមុខទៅទិសខាងកើត មានទ្វារបញ្ឆោត៣នៅទិសផ្សេងទៀត ចំណែកផ្ដែរទ្វារពិត មានក្បាច់ផ្កាជារាងដងធ្នូ។ នៅតាមស៊ុមទ្វារមានក្បាច់វិមាន អាកាសហៅថា វិមានអណ្ដែត។ អាយុកាលរបស់ប្រាសាទត្រូវបានកំណត់ ដោយសិលាចារឹកមួយផ្ទាំងដែលមានចុះកាលបរិច្ឆេទ ត្រូវនឹងឆ្នាំ ៦៦៧ នៃគ.ស ស្ថិតក្នុងអន្តរកាលរវាង រចនាបថព្រៃក្មេង និងកំពង់ព្រះ។ ការសិក្សាស្រាវជ្រាវបានរកឃើញនូវភស្តុតាងជាច្រើន ដែលបង្ហាញថា ទឹកដីជុំវិញទីក្រុងភ្នំពេញនេះ មានមនុស្ស រស់នៅតាំងពី ៣០០០ឆ្នាំមុនមកម៉្លេះ។ ដោយឡែក មន្ទីរបូជនីយដ្ឋានធ្វើអំពីស៊ីម៉ង់ប្រក់ក្បឿងមួយកន្លែង ត្រូវបានធ្វើឡើងនៅលើកំពូលភ្នំជិតប្រាសាទស្រីគ្រប់លក្ខណ៍។ មន្ទីរនេះមានទំហំប្រមាណ៣ម៉ែត្រក្រឡា និងមានធ្នើតម្កល់អដ្ឋិធាតុតូចល្មមនៅពីក្នុងមន្ទីរ។ ទីនេះ មាននៅសេសសល់ឆ្អឹងអវៈយវៈបន្តិចបន្តួចប៉ុណ្ណោះ ដែលខ្នោះឃ្នាងខ្លះ ក៏ត្រូវបានជញ្ជូនយកមកដាក់នៅលាយឡំជាមួយអដ្ឋិធាតុទាំងនេះដែរ។ សាក្សីបានឱ្យដឹងថា ពួកខ្មែរក្រហមបានសម្លាប់មនុស្សនៅតាមជើងភ្នំ និងលើភ្នំ ហើយនៅក្រោយឆ្នាំ១៩៧៩ រណ្ដៅទាំងនោះត្រូវបានគាស់ហើយជញ្ជូនអដ្ឋិធាតុមកតម្កល់នៅទីនេះ។",
    "descriptionEn": "There are two mountains of Phnom Prosit divided by a gully between Ponhea Leu and Angsnourl district. The southern mountains have little historical remains. The northern mountains, on the other hand, have a lot of history and ancient remnants, such as a large Buddha state in nirvana; and there is also an ancient temple left before the Angkorian period. The temple was built of bricks, but the top was broken. Lintels and colonettes were built of sandstone. The oldest temple in the area, built during the Chenla period, is called Srei Krubleak temple. The temple has a luxurious design, although it has been torn down or almost completely removed. The temple faces east, with three false doors on the other side, while the real door has a flower-shaped arch. Along the door frame there is Vimean Akas relief called Andet temple. The age of the temple is determined by an inscription dated to 667 A.D, in the transition period between the Prey Kmeng and Kampong Preah styles. The study found a lot of evidence that the land around Phnom Penh has been inhabited since the last 3,000 years.",
