    "id": "rac-k02007",
    "nameKh": "ព្រះសក្យមុនីចេតិយ",
    "nameEn": "Buddha’s Relics Stupa (Preah Sakyakmuni Chetdei",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ខ្លោងទ្វារព្រះសក្យមុនីចេតិយ ដែលស្ថិតនៅតាមបណ្ដោយផ្លូវជាតិលេខ៥ អមដោយទង់ជាតិនិងព្រះពុទ្ធសាសនា បាននាំផ្លូវភ្ញៀវទេសចរចូលទៅកាន់រមណីយដ្ឋានជាច្រើននៃភ្នំព្រះរាជទ្រព្យ។ ព្រះសក្យមុនីចេតិយបានសាងសង់ ឡើងយ៉ាងប្រណិតស្ថិតនៅលើកំពូល ភ្នំខ្ពស់ជាងគេនៅផ្នែកខាងជើង មានកំពស់៤០ម៉ែត្រ បានបញ្ចុះបឋម សិលា ឆ្នាំ១៩៩៦ ហើយកសាងរួចរាល់នៅឆ្នាំ ២០០២ ជាទីកន្លែងតំកល់ព្រះសារីរិកធាតុរបស់ព្រះសម្មាសម្ពុទ្ធ ដែលពីមុនតម្កល់នៅព្រះសក្យមុនីចេតិយទល់មុខស្ថានីតរថភ្លើងភ្នំពេញ។ មនុស្សគ្រប់រូបដែលមកដល់បរិវេណ ត្រូវដោះស្បែកជើង និងដោះមួកចេញដោយដើរទស្សនាជើងទទេ ហើយផ្នែក ខាងក្រោមព្រះសក្យមុនីចេតិយ ពុទ្ធបរិស័ទគ្រប់ទិសទីបាននាំគ្នាជាវ ព្រះពុទ្ធរូបមកតំកល់ទុកទីនេះចំនួន ៥៣៣៤អង្គ នេះបើតាមស្ថិតិ របស់ក្រសួងវប្បធម៌។ នៅទីកន្លែងផ្សេងមិនធ្លាប់មានតម្កល់ព្រះពុទ្ធបដិមាយ៉ាង ច្រើនបែបនេះឡើយ ព្រះពុទ្ធបដិមានិមួយៗបានរៀបចំឡើងយ៉ាងមានសណ្ដាប់ធ្នាប់ ក្រោមពន្លឺភ្លើងភ្លឺចែងចាំង ដ៍ស្រស់ស្អាតគួរ ជាទីជ្រះថ្លាក្រៃលែង។ ភ្ញៀវជាតិ និងអន្តរជាតិ ដែលបានមកទស្សនានៅទីនេះមានសេចក្ដី សោមនស្សរីករាយទាំងគ្រហស្ថរួមទាំងព្រះសង្ឃបានមកគោរពថ្វាយទៀនធូបផ្កាភ្ញីបូជាថ្វាយព្រះជាហូរហែជាពិសេសនៅថ្ងៃសំរាក។ នៅខាងឆ្វេងដៃក្បែរព្រះសក្យមុនីចេតិយ មានចេតិយធំៗចំនួនពីរនៅក្បែរគ្នា ចេតិយ ខាងជើងមានឆ្លាក់រូបដំរីដែលគេហៅថា “ចេតិយសាមពាន់” កសាងឡើងក្នុងគ្រិស្ត សករាជ១៦២៣ ដោយព្រះបាទជ័យជេដ្ឋា ដើម្បីបញ្ចុះព្រះបរមអដ្ឋិនៃព្រះបាទស្រីសុរិយោពណ៌ ជាព្រះរាជបិតា ចេតិយខាងត្បូងជាប់គ្នានោះកសាងឡើងក្នុងគ្រិស្តសករាជ១៨៩១ ដោយព្រះបាទសម្ដេចព្រះ នរោត្តម ដើម្បីបញ្ចុះព្រះបរមអដ្ឋិនៃព្រះបាទអង្គឌួង ជាព្រះរាជ បិតា បើឡើងតាមជណ្ដើខាងត្បូងឃើញមានចេតិយធំមួយ គឺជាចេតិយរបស់សម្ដេច ព្រះបាទស៊ីសុវត្ថិមុនីវង្ស ដែលមានក្បាច់រចនាស្អាតបាត ចំណែកឯចេតិយធំទាំងបី ដែលស្ថិត នៅលើភ្នំជ្រុងខាងជើង ត្រូវបានហៅថា “ចេតិយត្រៃត្រិង្ស”។",
    "descriptionEn": "The gate of Preah Sakyakmuni Chetdei decorated with nation flag and religion flag is on National Road No.5 which welcome many tourists to the natural resort of Phnom Preah Reach Troap. Preah Sakyakmuni Chetdei was magnificently built on highest summit on the north of 40 meters high. The grounding ceremony was celebrated in 1996, and it was completely constructed in 2002. This place is used to hold the relics of Buddha which before was housed opposite the railway station in Phnom Penh city. Everyone who arrives here has to take off their shoes and hats before allowing to walk around. Buddhists from everywhere impress their belief by buying small Buddha statue to put under the Preah Sakyakmuni Chetdei. According to the data from the Ministry of Culture and Fine Arts, there are about 5334 Buddha statues kept there up to now. Elsewhere, there have never been so many Buddha statues, each set up neatly under a beautiful, radiant light. National and international guests who came to visit here were very happy, including monks and nuns, who came to pay homage by candles, incense, flowers, and offerings to the gods, especially on holidays. On the lefthand side, near the Shakyamuni Stupa, there are two large stupas next to each other. The North Stupa with elephant sculpture is called “Chetdei Sampoan”, built in 1623 by king Chey Chetha to bury the remains of his father, king Srei Soryapor (Barom Reachea IV). The South Stupa, was built in 1891 by King Norodom to bury the remains of King Ang Duong, the father king. To climb up by the stair on the south, there is a big stupa, the stupa king Sisowath Monivong, which has a beautiful design. And the three large stupas on the northern corner of the mountain are called \"Trai Treung Stupa\".",
