    "descriptionEn": "Phnom Sa’ang is a cultural and natural recreation site with a pagoda built on top of the mountain, from which we can see the beautiful scenery that surrounds it. Phnom Sa’ang does not have as many trees as Phnom Thon Mon, but around there is a large lake rich in fish, waterlily and water green. And in addition to boating, tourists can also enjoy fishing. In rainy season, Phnom Sa’ang looks like an island surrounded by large surface of water. The pagoda also has some artifacts such as female deities, male deities with broken arms and pillar fragments. Tourists can climb up the low mountains and when they return, they can sit at a kiosk and relax, and order local food.",
