    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ប៉ែកខាងលិចនៃជើងភ្នំព្រះរាជទ្រព្យ មានវត្តមួយដ៏ស្រស់ស្អាត ដែលកសាងឡើងក្រោមការផ្ដួចផ្ដើម របស់ព្រះសពព្រះធម្មវិបស្សនា សំ ប៊ុនធឿន កេតុធម្មោ ជាអធិបតីពុទ្ធមណ្ឌលនិងជាអគ្គនាយកវិបស្សនាធុរៈសិក្សា នៃព្រះរាជណាចក្រកម្ពុជា។ ក្រៅពីសំណង់ទីសេនាសនៈនានាដ៏ស្អេកស្កះ ក្នុងទីវត្តនៅមានស្រះ សំណង់លម្អ ក៏មានតូបសម្រាប់តាជីយាយជីធ្វើវិបស្សនា និងសំណង់ដទៃ ជាច្រើន។ វត្តត្រូវបានចាត់ចូលជាវត្តទេសចរណ៍មួយប្រចាំខេត្ត។",
    "descriptionEn": "The western part of the foothills of Preah Reach Trop has a magnificent pagoda built under the initiative of e Dhamma Vipassana Sam Bunthoeun Keto Dhammo, President of the Buddhist Center and Director General of Vipassana Dhura Study of the Kingdom of Cambodia. Beside the buildings, there is a pond, decorative buildings, and cottages for laymen and nuns to meditate and other constructions. This pagoda is regarded as a tourism site in the province.",
