    "id": "rac-k02013",
    "nameKh": "វត្តព្រះវិហារសួគ៌",
    "nameEn": "Vihear Sour Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តនេះជាទីសក្ការៈបូជានិងជាទីបុរាណដ្ឋានប្រវត្តិសាស្ត្រផងដែរ។ វត្តមានព្រះវិហារពីរនិងចេតិយជាច្រើន ដែលមាននៅសល់វត្ថុបុរាណជាច្រើននៅខាងជើងព្រះវិហារ និងកូនចេតិយមួយធ្វើពីថ្មភក់លាបល័ក្ខ និងទិបមាស។ នៅខាងកើតព្រះវិហារមានត្រពាំងធំមួយដែលមានកូនកោះតូចមួយចំកណ្ដាល។ ផ្ដែរបុរាណមួយចំនួនត្រូវបានភ្ជាប់ទៅនឹងបេតុង និងក្នុងខ្ទមអ្នកតាមានដំកល់បំណែកបល្ល័ង្គពីថ្ម ថ្លើមអណ្ដើកដែលជាសិលាចារឹក។ វត្តនេះជាបូជនីយដ្ឋានដ៏សក្ដិសិទ្ធិមួយល្បីល្បាញក្នុងប្រទេស ដែលមានមហាជនរាប់ពាន់នាក់ ទៅបូជាបែរបន់តាមប្រាថ្នាផេ្សងៗ រួមទំាងព្រះរាជា ព្រះរាជវង្សានុវង្ស នាម៉ឺនសព្វមុខមន្រ្តីផងដែរ។ វត្តវិហារសួគ៌ មានរឿងនិទានតំណាលថាជាព្រះរាជទ្រព្យដែលព្រះរាជាបក្សីចាំក្រុង ទ្រង់កសាងទុកជាអនុស្សាវរីយ៍ ត្រង់ទីដែលទ្រង់រត់គេចពីកងទ័ពជាមួយតាគហេ ក្នុងរវាងគ.ស ១០២៨ ឬ២៩។ តាមប្រវត្តិ គឺពេលដែល បុរសម្នាក់ឈ្មោះដំបងគ្រញូង មានមហិទ្ធិឬទ្ធិខ្លាំងពូកែ បានឡើងសោយរាជ្យក៏បង្គាប់ឲ្យធ្វើគុតព្រះរាជវង្សានុវង្សមុន ហើយនៅរស់ព្រះម្នាងម្នាក់ទ្រង់ព្រះគភ៌បានភៀសខ្លួនទៅស្នាក់នៅជាមួយ តាគហេ និង យាយលាក់។ លុះពេលព្រះរាជបុត្រប្រសូត្រមកគេឃើញមានលាយលក្ខណ៍កងចក្រនៅបាតព្រះហស្តនិងព្រះបាទ ហើយពេលតាយាយនិងព្រះម្នាងទៅច្រូតស្រូវកំដៅថៃ្ងចាំងមកត្រូវព្រះរាជកុមារក៏មានបក្សីមួយមកកាងស្លាបបាំងពីលើ ទើបដាក់ព្រះនាមថា\"បក្សីចាំក្រុង\"។ ក្នុងរជ្ជកាលព្រះបាទព្រហ្មកិល (ពញាក្រែក) ដែលសោយរាជ្យបន្តពី ដំបងគ្រញូងនោះ ក៏បានជ្រាបទំនាយថានឹងមានស្ដេចថ្មីចូលមកជ្រែករាជ្យ ទើបចាត់កងទ័ពដេញតាមចាប់ បក្សីចាំក្រុង និងតាគហេដល់ទីកន្លែងខាងលើនេះ។",
    "descriptionEn": "This pagoda is a shrine and also a historical archeological site. There are two temples and stupas with many artifacts at the north of the temple and a small stupa made of sandstone, and golden color painting. At the east of the Buddhist temple, there is a big pond, where a small island is located in the middle. Some ancient lintels are attached to concrete, and in the deity shrine, there is a fragment of thrones made from jet stones which is an inscription. This pagoda is a famous sacred shrine in the country where thousands of people go to worship according to various wishes, including the royal family, princes, nobles and officials. Vihear Sour pagoda has a legend about the king Baksei Cham Krong who built this place in gratitude for his escaped from the army with Ta Kahé between 1028 or 1029 A.D. According to history, when a powerful man, Dambang Kror Nhung, ascended the throne, and order to assassinate all member of the royal family first. Fortunately, one survived princess who were pregnant fled to stay with an old man, Ta Kahé, and an old woman, Yeay Leak. When the baby was delivered, a print of discus was found in his palm. The baby was sheltered by a birds’ wing when the princess, the grandfather and grandmother did rice harvesting in paddy fields. As so, the baby was named “Baksei Cham Krong”. During the reign of King Prom Kel (Ponhea Krek), who succeeded to the throne from Dambang Kror Nhung, he also knew the prophecy that there would be a new king to fight for the Kingdom, so he sent an army to arrest Baksei Cham Krong, and Ta Kahé.",
