    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តនេះមានសំណង់ដែលបានកសាងឡើងឱ្យមើលឃើញកំពូលប្រាំ ដូចជាកំពូលប្រាសាទអង្គរវត្តដែរ។ មុនពេលទៅដល់វត្ត យើងត្រូវឆ្លងកាត់ស្ពានមួយមានប្រវែង១០០ម៉ែត្រ ដែលពីមុនជាស្ពានឫស្សី ហើយប្រកបដោយសំណង់ថ្មីៗជាច្រើនគួរចាប់អារម្មណ៍។ ប៉ុន្តែអ្វីដែលបង្កប់ភាពអស្ចារ្យ គឺនៅចម្ងាយ ប្រមាណ ៥០០ម៉ែត្រខាងលិចវត្ត មានទួលជាកន្លែងសក្ការៈបូជាមួយ ដែលល្បីល្បាញ ហើយមានអ្នកគោរពបូជាជាច្រើន ដែលមានឈ្មោះថា «ដំបូកខ្មៅ»។ ទីនោះមានដំបូកមួយមានដុះ (ឬបានដាំ?) ដើមប្រទាលពេញខាងលើ ដែលគេចាត់ទុកជាដំណាក់របស់អ្នកមានបុណ្យ ឬស្តេច។ គេជឿថា ដំបូកខ្មៅនេះ គឺជាអតីតវាំងពីមុនមក ពីព្រោះគេបានរកឃើញវត្ថុបុរាណជាច្រើន និងសម្ភារៈ ប្រើប្រាស់ ដូចជាចាន និងឆ្នាំងបុរាណ។ ឥឡូវនេះ ដំបូកខ្មៅត្រូវបានគេរៀបចំ និងថែរក្សា បានយ៉ាងល្អដោយដូនចាស់ជាច្រើន ហើយមានសំណង់ជាច្រើនលើទីទួលនោះ បន្ទាប់ពីការបន់ស្រន់ បានសម្រេចរបស់អ្នកមានជំនឿ។ ទីតាំងជាគូជាមួយដំបូកខ្មៅ គឺនៅខាងត្បូងទីនោះប្រមាណ ៣០០ ម៉ែត្រ មានទួលមួយទៀតដែលមានទ្រង់ទ្រាយមិនខុសពីទីតាំងដែលរៀបរាប់ខាងដើម ហៅថា «ក្របៅជ្រុំ» ដែលមានការកសាងសំណង់បូជាដល់ទីសក្ការនោះដែរ។",
    "descriptionEn": "This pagoda was constructed to see the top-five-tower as the towers of Angkor Wat. Before reaching the pagoda, we have to cross a 100-meter-long bridge, which used to be a bamboo bridge and has many interesting new constructions. But what amazing is that about 500 meters west of Wat Tuol is a famous place of worship and there are many worshipers called \"Dambok Khmao\". There was a lump growing (or planted?) full of succulent plants above, which was considered the house of a sacred person or a king. It is believed that Dambok Khmao was a former palace because many artifacts and utensils such as plates and pots were found. Dambok Khmao is now well-prepared and maintained by many old women, and there are many constructions on the hill after the faithful praying of some believers. The site about 300 meters to the south paired with Dambok Khmao is another hill in similarshape called Krobao Chhrum where a shrine is built on top.",
