    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "រមណីយដ្ឋាននេះមានសម្រស់ស្រស់ស្អាត អមជុំវិញខ្ពបទន្លេមេគង្គ ដែលហូរកាត់តំបន់នេះ នាំជីជាតិស្រោចស្រប់ចម្ការដំណាំច្រើនប្រភេទ។ កៀនស្វាយជាឈ្មោះស្រុកមួយនៃខេត្តកណ្ដាល មានខ្ពបមួយ ដែលកាលពីមុនវាមិនមែនជារមណីយដ្ឋានទេ ទើបតែចាប់ផ្ដើមបន្ទាប់ពីឆ្នាំ ១៩៧៩ និងមានការទៅលេងកម្សាន្តនៅវត្តកៀនស្វាយក្រៅជាញឹកញាប់ ទើបទីនេះបានក្លាយជារមណីយដ្ឋានសំខាន់ដោយហេតុថានៅជិតក្រុងភ្នំពេញជាងគេ។ ក្នុងរមណីយដ្ឋាន មានលក់ម្ហូបអាហារនិងចំណី ជាច្រើនមុខ ជាពិសេសមានតូបតាមមាត់ខ្ពបស្អេកស្កះ ដែលអាចឱ្យ ភ្ញៀវអង្គុយសម្រាក និងបញ្ជាទិញម្ហូបអាហារជាច្រើនមុខ ព្រមទាំងអាចលេងទឹកខ្ពបនោះផងដែរ។ រមណីយដ្ឋាននេះបានទាក់ទាញភ្ញៀវ ទេសចរជាច្រើន ពិសេសអ្នកនៅក្នុងទីក្រុង ភ្នំពេញ តែក៏សូមពិនិត្យមើលតម្លៃសិនមុនធ្វើការបញ្ជាទិញម្ហូប។",
    "descriptionEn": "This resort has scenic natural beauty around the alluviums of the Mekong River, which flows through this area, bringing fertilizer to irrigate a variety of crops. Kien Svay is the name of a district in Kandal province, which used to be not a resort. It only started after 1979 since more frequent visits of Buddhists to Wat Kien Svay Krao. This place has become an interesting and convenient resort because of its close-distance to Phnom Penh.",
