    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ប្រាក់ជារ៉ែធម្មជាតិក្រោមដីដ៏មានតម្លៃមួយប្រភេទ និងអាចយកទៅឆ្នៃជារបស់ប្រើប្រាស់និងវត្ថុលំអផ្សេងៗ ឬជា វត្ថុអនុស្សាវរីយ៍។ ចម្លាក់ប្រាក់នេះក៏អាចបង្ហាញពីអត្តសញ្ញាណនៃវប្បធម៌ជាតិផងដែរ តាមរយៈក្បាច់ចម្លាក់ខ្មែរ ដែលឆ្លាក់ដោយដៃផ្ទាល់របស់ជាងទង។ ចម្លាក់ប្រាក់ជាប្រភេទកាងារមួយដែលទាមទារ ការយកចិត្តទុកដាក់ និងដាក់អារម្មណ៍ច្រើន។ លើសពីនេះ ការងារចម្លាក់ប្រាក់នេះត្រូវការប្រើពេលវេលាយូរ ទើបបានជាផលិតផល សម្រេចមួយដែលល្អ។ ជាងចម្លាក់ប្រាក់សព្វថ្ងៃមានការថយចុះ ខណៈពេលដែលតម្រូវការភ្ញៀវនៅតែមាន។ មជ្ឍមណ្ឌលសហព័ន្ធចម្លាក់ ប្រាក់ ស្ពាន់ កម្ពុជា មានទីតាំងនៅឃុំកោះចិនស្រុកពញាឮ ដែលស្ថិតនៅច្រាំងទន្លេម្ខាងទៀត ក៏ជាទីដែលប្រមូលផ្ដុំនូវ ជាងទងជាច្រើន ដែលទេសចរអាចចូលទស្សនានិងជាវវត្ថុសិល្បៈផ្សេងៗផងដែរ។ សព្វថ្ងៃនេះមានការប្រើប្រាស់ស្ពាន់លឿងជាវត្ថុធាតុដើមសម្រាប់ធ្វើជាគ្រឿងចម្លាក់ផងដែរ។",
    "descriptionEn": "Silver is a precious underground mine and can be grinded to materials or tools, ornaments or souvenir stuffs. Silver carvings represent the identity of national culture through Khmer carvings carved by professional silver smith. Silver carving is a kind of job which requires strong focus, and attention. In addition, this kind of job needs more time to produce each of the stuff luxuriously and perfectly. The number of silver carvers are decreasing although the demand of customers is still available. The Cambodian Copper Silver Sculpture Federation Center, a gathering place of many craftsmen, is located in Koh Chen Commune, Ponhea Leu District, where tourists visit and buy various art objects.",
