    "descriptionKh": "នៅលើដែនដីកោះនៅកណ្ដាលផ្ទៃសាគរនៃទន្លេមេគង្គរមណីយដ្ឋានចម្ការស្នេហ៍ ឬ Silk Island បានទាក់ទាញភ្ញៀវទេសចរទាំងខ្មែរ និងបរទេសចេញចូលមិនចេះដាច់ជារៀងរាល់ថ្ងៃ។ ទីនេះមានសេវាកម្មច្រើនសម្រាប់ម្រើអារម្មណ៍ទេសចរទាំងខ្មែរ និងបរទេសដូចជា ចម្ការដើមមនសម្រាប់ចិញ្ចឹមសត្វដង្កូវនាង ជាប្រភពនៃការផលិតសរសៃសូត្រដ៏ល្អប្រណីត សំណង់ផ្ទះជនជាតិភាគតិច៤០ខ្នង សម្រាប់ទុកឲ្យភ្ញៀវចូលទស្សនា ដោយផ្ទះនីមួយៗអាចផ្ទុកមនុស្សបានចំនួនប្រមាណជាបីបួននាក់ប៉ុណ្ណោះ។ ក្រៅពីនេះក៏មានក្យូសប្រក់ស្បូវធំៗមួយចំនួន ដែលជាទីកន្លែងសម្រាក និងទទួលទានអាហារ និងការចូលទស្សនាសិប្បកម្មតម្បាញហូល ផាមួង ពីសូត្រដង្កូវនាងជាដើម។ ដោយឡែកទីកម្សាន្តទឹកនៃចម្ការស្នេហ៍មិនមែនជាអាងហែលទឹក ដែលមានពណ៌ថ្លាខៀវស្រងាត់ និងជីកសង់នៅលើដីគោកដូចតាមសណ្ឋាគារធំៗនោះឡើយ តែអាងហែលទីនេះ ត្រូវបានគេយកចំណែកមួយផ្នែកតូចនៃដងទន្លេមេគង្គផ្ទាល់តែម្ដងដោយគ្រាន់តែសង់ស្ពានដើរព័ទ្ធជុំវិញ និងជណ្ដើរតោងឡើង ហើយនៅបាតក្រោមជាប្រភេទដីខ្សាច់ ខណៈពណ៌របស់ទឹកវិញគឺមានសភាពប្រែប្រួលទៅរដូវកាលនៃទឹកទន្លេតែម្ដង។",
    "descriptionEn": "On an island in the middle of the Mekong River, the Chamkar Snae resort, or Silk Island, attracts both Cambodian and foreign tourists every day. There are many services for both Cambodian and foreign tourists, such as mulberry plantation for raising worms which is a source of luxury silk production. There are about 40 ethnic houses for guests to visit, which each house can hold a few people. Besides, tourists can sightsee silk weaving from silkworm to make silk cloth (Hol, Phamourng ect.), and resting and eating meals in several big kiosks. In particular, Chamkar Snae water park is not a swimming-pool with blue and clear water as in big hotels, but this natural pool is a small part of the Mekong River by just build a bridge around and climbing- stairs. The sand is at the bottom and the color of the water changes seasonally.",
