    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ក្រុមហ៊ុន ស្តាឌេវឺឡុបម៉េន និង ស្កាយឡេន បានចូលរួមបណ្ដាក់ទុន ដើម្បីរៀបចំកន្លែងកម្សាន្ត ប្រភេទរីស៊ត និង អភិវឌ្ឍជាខុនដូ។ រីស៊តនេះមានការជិះសេះ ម៉ូតូ និងការប្រណាំងឡាន និងឧទ្យាន ប្រកបដោយបទដ្ឋានអន្តរជាតិ ធ្វើឱ្យតំបន់នេះ ក្លាយទៅជាទីក្រុងរណបមួយលាតសន្ធឹង នៅលើផ្ទៃដី ជាង ២០០០ ហិកតា ស្ថិតនៅក្នុងតំបន់ដ៏ល្អមួយដែលមានវាលស្មៅខៀវស្រងាត់ មានអំណោយផល សម្រាប់ការរស់នៅ។ តំបន់វិហារសួគ៌ មានការអភិវឌ្ឍយ៉ាងឆាប់រហ័ស ដែលខុសពីរាជធានី ភ្នំពេញមានការកកស្ទះចរាចរណ៍យ៉ាងខ្លាំង ជាពិសេសនៅពេលដែលរដ្ឋាភិបាលបានគ្រោង សាងសង់ស្ពានឆ្លងទៅតំបន់នោះធ្វើឱ្យតំបន់នេះក្លាយជាគោលដៅទេសចរណ៍ថ្មី មានចំងាយត្រឹមតែ១៧ គ.ម. ប៉ុណ្ណោះពីរាជធានីភ្នំពេញ។ តាមគម្រោង ទីនេះនឹងមានការរៀបចំជាសួនទំនើប ព្រមទាំងសង្វៀនប្រដាល់ដ៏ធំមួយ ខ្នាតអន្តរជាតិបម្រើដល់ការប្រកួតប្រដាល់គុនខ្មែរ ប្រដាល់សកល និងវ៉ៃដាក់ទ្រុងផងដែរ។",
    "descriptionEn": "STAR5 Development and SKYLAND have jointly invested approximately US $ 20 million to organize this amusement park, , and develop resorts and condominiums. The resort features horseback riding, motorbike and car racing and an international standard park, making the area a satellite city of more than 2,000 hectares in a prime location with lush green pastures for luxurious and convenient living. Vihear Sour is a fast-growing area that, unlike Phnom Penh, is heavily congested, especially when the government plans to build a bridge over the area, making the area a new tourist destination which is in a distance of 17 km away from Phnom Penh. As set in the development plan, there will be a modern park as well as a large international boxing arena to serve Khmer boxing, world boxing and wrestling.",
