    "descriptionKh": "«ភូមិត្នោត ភូមិឋានសុខភាព» ជាគោលដៅពេញនិយមទាក់ទាញភ្ញៀវទៅសម្រាកកម្សាន្តលម្ហែកាយនៅ ពេលទំនេរពីការងារ។ មិនខុសពីឈ្មោះរបស់វាទេ រមណីយដ្ឋានភូមិត្នោតនេះស្ថិតនៅកណ្ដាលវាលស្រែ ព័ទ្ធជុំវិញទៅដោយដើមត្នោត និងរុក្ខជាតិតូចធំពណ៌ខៀវស្រងាត់ ដែលត្រូវបានគេថែរក្សា ដើម្បីតុបតែង ជាមួយសំណង់ធ្វើពីឫស្សី និងដើមត្នោតជាសម្បត្តិធម្មជាតិរបស់ខ្មែរ។ ការតុបតែងដ៏ត្រជាក់ភ្នែកដូច្នេះ បានធ្វើឲ្យទីនេះ ក្លាយទៅជាទីទាក់ទាញភ្ញៀវ រួមទាំងមានរសជាតិម្ហូបខ្មែរ មាន់ដុត និងសម្លកកូរត្នោតផងដែរ។ រមណីយដ្ឋានធ្លាប់ជាទីទួលខ្ពស់មួយមិនលិចទឹក មានផ្ទៃដីជាងពីរហិកតា មានដើមត្នោត១០០ ដើម និងរុក្ខជាតិតូចធំរាប់សិបដើម។ នៅរៀងរាល់ថ្ងៃអាទិត្យ ភូមិត្នោតមានផ្សារតូចមួយនៅចាំស្វាគមន៍ភ្ញៀវទេសចរ ដែលនៅផ្សារនោះមាន លក់បន្លែ ត្រីសាច់ និង វត្ថុអនុស្សាវរីយ៍ កែច្នៃចេញពីវត្ថុធាតុដើមធម្មជាតិ ច្រើនសម្រាប់ភ្ញៀវទេសចរ ហើយអ្នកដែលត្រូវបានអនុញ្ញាតឲ្យយករបស់នោះមកលក់ទៀតសោតសុទ្ធតែជា កុមារកំព្រា និងស្ត្រីមេម៉ាយនៅក្នុងភូមិឃុំនេះ ដែលទទួលបានការបណ្ដុះបណ្ដាលលើជំនាញកែច្នៃ និងរៀនចម្លាក់ ដោយអង្គការក្រៅរដ្ឋាភិបាល។ រមណីយដ្ឋានលំអដោយស្រះទឹក អាងហែលទឹក ភោជនីយដ្ឋាន និងមានរូបសំណាក បុរសពាក់មួកស្លឹកត្នោត ស្ពាយអង្រុត និងស្ត្រីទូលផ្លែឈើមួយល្អីយ៉ាងពេញរង់ចាំស្វាគមន៍ភ្ញៀវទេសចរ។ ចំណុចពិសេសមួយគឺក្នុងភោជនីយដ្ឋាន ទាំងតុ កៅអី សង្ហារឹមនានា សុទ្ធសឹងធ្វើពីដើមត្នោត ហើយក៏មាន ស្ករត្នោត និងទឹកត្នោត ដែលផលិតនៅទីនេះផ្ទាល់។",
    "descriptionEn": "“Phum Thnaot, Healthy Village” is a popular destination to attract guests to relax in their free time. As its name, this Phum Thnoat resort is located in the middle of paddy rice fields, surrounded by palm trees and lush green plants that have been preserved to decorate with bamboo structures and palm trees, a natural resource of Cambodia. The cool decoration and the taste of Khmer cuisines such as Somlor korko thnaot and girlled chickens make the place amazingly attractive to tourists. The resort used to be a high hill, not flooded, with an area of more than two hectares, with 100 palm trees and dozens of small and large plants. Every Sunday, Phum Thnaot has a small market selling vegetables, fish, meat and souvenirs made from natural raw materials for tourists waiting to welcome tourists. The sellers are orphans and widows in this village who have been trained in processing skills and carvings by NGOs. The resort is adorned with ponds, swimming pools, restaurants and statues of men wearing brown hats and carrying fish traps, and women carrying a basket full of fruit to welcome visitors. A special point is that in the restaurant, all the tables, chairs and furniture are made from palm trees, and there is also organic palm sugar and palm juice made here.",
