    "nameEn": "Phum Phkar Trokourn Park",
    "categorySlug": "nature",
    "categoryKh": "ធម្មជាតិ & ទឹកធ្លាក់",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ទីលម្ហែ ញាំអាហារស្រុកស្រែ ហើយភ្ញៀវក៏អាចជិះទូកលេងកម្សាន្ត ស្រូបយកខ្យល់អាកាសត្រជាក់កាយបាននៅ រមណីយដ្ឋាន ភូមិផ្កាត្រកួន។ រមណីយដ្ឋានបែបធម្មជាតិដ៏ស្រស់ស្រាយត្រជាក់កាយ និងស្អាតប្លែកភ្នែកមួយ ដែលទីតាំងនេះកាលពីមុនជាដីចម្ការស្វាយ ចម្ការចេកលើផ្ទៃដីប្រហែល ១០០ ហិកតា មានកន្លែងកម្សាន្តជាច្រើនដូចជា បឹងនិស្ស័យជាបឹងធម្មជាតិសម្បូរត្រី ដែលនៅជុំវិញមាត់បឹងមានត្រកួនដុះព្រោងព្រាតស្រស់បៃតងខ្ចីដែលស័ក្ដិសមទៅនឹងឈ្មោះថា «ភូមិផ្កាត្រកួន»។ សួនបន្លែសិរីរាង្គគ្មានជាតិគីមីពណ៌បៃតងស្រស់ដូចជា សណ្ដែកកួរ ស្ពៃក្ដោប សាឡាដ ស្លឹកបាស និងននោងជាដើម។ នៅប្របមាត់បឹងមានក្យូសឈើប្រក់ដំបូលស្បូវ សម្រាប់អង្គុយលម្ហែអារម្មណ៍និងញុំាអាហារសុទ្ធសឹងជាម្ហូបខ្មែរ។ ទន្ទឹមនឹងនោះភ្ញៀវទេសចរក៏អាចមកសម្រាកនៅផ្ទះលម្ហែបែបបុរាណសម័យឧដុង្គបានផងដែរ។",
    "descriptionEn": "It is a recreational place to relax, eat local food, ride boats to enjoy gentle breeze. A beautiful natural resort used to be a mango, banana plantation on an area of about 100 hectares. There are many recreational places such as Boeung Nissay, a natural lake rich in fish and water green around the lake which reflects the greenery landscape fit the name \"Phka Trakoun Village\". There are organic vegetable gardens without chemicals such as beans, cabbage, lettuce, bass leaves and watermelon. At the lake, there is a wooden thatched roof for relaxing and eating Khmer food. Besides, tourists can also come to relax in relaxing houses in a style of Udong era.",
