    "descriptionKh": "ភូមិសេអាមេត្រីមានចម្ងាយប្រហែល ២០ គីឡូម៉ែត្រ ពីភ្នំពេញ ដែលជាទីកម្សាន្តងាយស្រួលសម្រាប់អ្នកខ្ជិលធ្វើដំណើរឆ្ងាយ នៅថ្ងៃសម្រាក។ ជាទីដែលមានខ្យល់អាកាសបរិសុទ្ធ កន្លែងលេងកីឡា អាងហែលទឹក។ តម្លៃសំបុត្រសម្រាប់ចូលកម្សាន្ត ត្រឹមតែ ១ ដុល្លារប៉ុណ្ណោះ សម្រាប់ភ្ញៀវជាតិ និង តម្លៃ ៥ដុល្លារសម្រាប់ភ្ញៀវបរទេស។ ភូមិកម្សាន្តសេអាមេត្រី មានក្យូសអង្គុយជាប់មាត់ទឹក មានអាងហែលទឹក កន្លែងលេងកីឡាជាច្រើនប្រភេទ និង មានលក់ម្ហូបអាហារ បង្អែម ភេសជ្ជៈផ្សេងៗក្នុងតម្លៃសមរម្យ។",
    "descriptionEn": "Phum Se Ametrey resort is about 20 km from Phnom Penh, which is a convenient place for people who like short-travelling holidays. It is a recreational place with fresh air, sports facilities, swimming pool. Tickets are only $ 1 for national tourists and $ 5 for foreign tourists. Phum Se Ametrey resort has seat kiosks by the water, a swimming pool, a variety of sports facilities and sells food, desserts and other drinks at reasonable prices.",
