    "descriptionKh": "ពោធិ៍ទនេ្ល ជាកន្លែងឃុំឃាំងធំមួយប្រចាំស្រុកកោះធំ ក្នុងសម័យខ្មែរក្រហម ដែលមានអ្នកទោសរាប់ពាន់នាក់ជាប់គុកនៅទីនោះ។ នៅ ឆ្នាំ១៩៩០ មន្ទីរបូជនីយដ្ឋានពោធិ៍ទនេ្ល ត្រូវបានសាងសង់ឡើងក្រោមការជួយឧបត្ថម្ភពីសប្បុរសជនមួយចំនួន។ ឆ្អឹងលលាដ៏ក្បាល និងឆ្អឹង អវៈយវៈយ៉ាងច្រើនដែលគាស់ចេញពីរណ្ដៅចំនួន៥៥នៅក្បែរនោះ បានត្រូវជញ្ជូនមកដាក់តម្កល់នៅក្នុងមន្ទីរបូជនីយដ្ឋាន។ តាមការប៉ាន់ស្មានជនរងគ្រោះដែលស្លាប់ នៅក្នុងបរិវេណពោធិ៍ទនេ្លនេះ មានចំនួនប្រហែល៣៥,០២៧នាក់។ ឯការធ្វើបុណ្យឧទ្ទិសដល់វិញ្ញាណក្ខន្ធអ្នកដែលស្លាប់ទៅនៅទីតាំងពោធិ៍ទនេ្លនេះ បានកើតឡើងស្ទើរតែរាល់ឆ្នាំ។ រហូតមកដល់សព្វថ្ងៃ ប្រជាជនកម្ពុជាទូទៅ នៅតែអាចមើលឃើញមន្ទីរបូជនីយដ្ឋាននេះយ៉ាងច្បាស់ក្រឡែតពីត្រើយម្ខាង និងអាចទៅមើលដោយផ្ទាល់បាន។ តាមការស្រាវជ្រាវរបស់ក្រុមព្រះសុរិយា នៅទីនេះគេបានសម្លាប់តារាចម្រៀង លោកស៊ិន ស៊ីសាមុត និង តារាភាពយន្ត លោកគង់ សំអឿន ផងដែរ។",
    "descriptionEn": "Po Tonle was a large detention center in Koh Thom district during the Khmer Rouge regime, where thousands of prisoners were imprisoned. In 1990, the Po Tonle Monument was built with the support of a number of philanthropists. A large number of skulls and limbs unearthed from 55 nearby pits were transported to the monument. It is estimated that 35,027 people died in the Po Tonle area. A memorial ceremony for the spirit of the dead at Po Tonle takes place almost every year. To this day, Khmer people can still see the monument clearly from one side or in person. According to the research of Preah Sorya team, this place is where Sin Sisamuth, a famous Cambodian singer, and Kong Sam Oeun, a famous Cambodian film actor, were also killed.",
