    "id": "rac-k02027",
    "nameKh": "ស្តូបវត្តរកាកោង, ស្តូបវត្តកែវមុនីជោតិ",
    "nameEn": "Stupa of Roka Koang Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តនេះមានឈ្មោះល្បីល្បាញខាងសំណង់ព្រះវិហារបុរាណដ៏ល្អ ហើយមានប្រវត្តិជូរចត់នាសម័យប៉ុលពត ថាជាមន្ទីរសន្តិសុខ ជាកន្លែងឃុំឃាំងនិងសម្លាប់អ្នកទោសជាច្រើន។ សាក្សីម្នាក់នៅវត្តកែវមុនីជោតិ រកាកោង បាននិយាយថា នៅពេលដែលច្រាំងទនេ្លបាក់ស្រុតចុះទៅក្នុងទឹក ឆ្អឹងជនរងគ្រោះមិនទាន់បានគាស់មួយចំនួនកប់នៅទីតាំងសម្លាប់ប៉ែកខាងត្បូងកោះ ក៏បានធ្លាក់ចូលក្នុងទនេ្លដែរ។ ចំណែកឆ្អឹងដែលនៅសេសសល់ពីការធ្លាក់ចូលក្នុងទនេ្ល ត្រូវប្រជាជនគាស់ចេញពីរណ្ដៅ ហើយត្រូវជញ្ជូនយកទៅតម្កល់ទុកនៅមន្ទីរបូជនីយដ្ឋានមួយក្នុងវត្តនេះ។ គេបានសន្និដ្ឋានថា ខ្មែរក្រហមបានសម្លាប់ជនរងគ្រោះអស់រាប់ពាន់នាក់នៅលើទីតាំងសម្លាប់កោះមរណៈ ដែលនៅក្នុងទន្លេទល់មុខវត្តនេះ។ អដ្ឋិធាតុដែលកំពុងតែដាក់តម្កល់នៅក្នុងបូជនីយដ្ឋាននេះ គឺបានគាស់ឡើងនៅឆ្នាំ១៩៨២ក្នុងចេតិយមួយនៅខ្លោងទ្វារខាងជើង។ ក្រៅពីនេះ ក៏មានជំនឿថា ចេតិយមួយទៀតនៅខាងជើងព្រះវិហារជាចេតិយរបស់ ក្រឡាហោមគង់ ដែលគេជឿថាមិនស្លាប់ដោយសារបារាំងចាប់ផ្អោបបំពង់ផ្សែងកប៉ាល់នោះទេ ហើយបានភៀសខ្លួនមកនៅទីនេះដល់អាយុខ័យ។ ជំនឿមួយទៀតគឺទាក់ទងនឹងរឿងបក្សីចាំក្រុង ដែលដើមរកានៅទីនេះបានកោងទៅជាប់ដើមល្វាពីត្រើយទន្លេម្ខាងទៀត ហៅថា «រកាកោង ល្វាទេ»។",
    "descriptionEn": "This pagoda is famous for its beautiful ancient temples and its bitter history during the Pol Pot era when it was used as a security center, a place where many prisoners were detained and killed. A witness at Wat Keo Moni Chote Roka Koang said that when the riverbank slid into the water, some of the unclaimed victims buried at the killing site on the south side of the island also fell into the river. The bones left over from falling into the river were dug out of the graves and transported to the shrine in the pagoda. It is estimated that the Khmer Rouge killed thousands of victims at the site of the Death Island massacre in the river opposite the pagoda. The remains placed in this shrine were unearthed in 1982 from the stupa at the North Gate. It is believed that another stupa north of the temple is the stupa of Krola Hom Kong, believed not to have died because the French smashed the chimney of the ship and fled here to old age. Another belief is related to a legend of Baksei Chamkrong which there was a Roka tree grew with L’vea tree from another bank of the river, and it is called “Roka Koang L’vea Te”.",
