    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ផ្នែកមួយនៃមន្ទីរសន្តិសុខសាលាត្រពាំងស្វារបស់ខ្មែរក្រហម ដែលជាអតីតសាលាគរុកោសល្យ (វិក្រិតការ) បានត្រូវផ្លាស់ប្ដូរទៅជាកន្លែងតំកល់អដ្ឋិធាតុដែលមានលលាដ៏ក្បាលមនុស្សរាប់ពាន់គរជាជង់ៗ ប្រហែលជាកំពស់២ម៉ែត្រ។ មួយរយៈកាលក្រោយមក ដោយសារកង្វះការថែទាំ និងដោយសារសត្វ ពាហនៈស៊ីផង ឆ្អឹងមួយភាគត្រូវបានបំផ្លាញ និងបាត់បង់។ ដោយហេតុនេះហើយ ប្រជាជន និងអ្នកផ្ដើម កសាងផេ្សងទៀត បានសហការគ្នាកសាងមន្ទីរបូជនីយដ្ឋានថ្មីមួយទៀត ដែលមានទីតាំងស្ថិតនៅប៉ែកខាង លិចអគារគុកដែលត្រូវបានប្រើប្រាស់ជាកន្លែងតម្កល់អដ្ឋិធាតុចាស់។ អដ្ឋិធាតុត្រូវបានបពា្ចលទៅខាងក្នុង ហើយចាក់សោរ ពីក្រៅ ព្រមទាំងមានអ្នកយាមត្រឹមត្រូវផង។",
    "descriptionEn": "A Tropang Sva School, a former pedagogical school, is a section of the security department of the Khmer Rouge, and has been transformed into a two-meter-high mausoleum with thousands of skulls. Some time later, due to lack of care and disturbance from animals, most pieces of bones were destroyed and lost. As a result, residents and other initiators have teamed up to build a new shrine located west of the prison building, which will be used as a repository to replace the old one. The bones are kept inside and locked. There is a guard taking care the place for safety and cleanness. In the resort, there are many kinds of food and drinks, especially small restaurant along the alluvium bank, where tourists can relax and order a variety of food, as well as bathe in the alluvium pond. This resort attracts many tourists, especially those in Phnom Penh. Tourists are usually recommended to check the price before ordering food.",
