    "id": "rac-k02030",
    "nameKh": "ស្តូបឧដុង្គ",
    "nameEn": "Udong Stupa",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ភ្នំនេះមានឈ្មោះបីគឺ ភ្នំឧដុង្គ ភ្នំព្រះរាជទ្រព្យ និង ភ្នំអដ្ឋរស្ស។ ឧដុង្គ ជាខ្សែភ្នំមួយដែលលាតសន្ធឹងពីជើងទៅត្បូង ប្រវែង ១៥០០ ម៉ែត្រ និង ទទឹង ៧០០ ម៉ែត្រ។ ភ្នំនេះមានកំពូល ៥ គឺ កំពូលចេតីយ៍ទន្ទឹម កំពូលត្រៃត្រឹង្គ កំពូលភ្នំចេតីយ៍កំពូលបួន ព្រះអង្គចូលបរិនិព្វាន្ត និងកំពូលភ្នំអរិយកាស្សប។ ភ្នំនេះមានរាងដូចជាសត្វនាគ ហើយនៅលើកំពូលភ្នំមានចេតីយ៍ របស់អតីតព្រះមហាក្សត្ររួមមាន ចេតិយព្រះអង្គឌួងសាងឡើងក្នុងឆ្នាំ១៨៩១ ចេតិយព្រះមុនីវង្ស ចេតិយព្រះស្រីសុរិយោពណ៌ មានឆ្លាក់រូបដំរី ហៅថា «ចេតិយសាមពាន់» សាងឡើងក្នុងឆ្នាំ ១៦២៣ ចេតិយព្រះចន្ទរាជាជាដើម។ ចំណែកឯចេតិយធំទាំងបី ដែលស្ថិត នៅលើភ្នំជ្រុងខាងជើង ត្រូវបានហៅថា “ចេតិយត្រៃត្រិង្ស”។ នៅតាមជើងភ្នំនេះ មានតូបជាច្រើនសង់ជាប់ៗគ្នា សម្រាប់ទេសចរសម្រាកកម្សាន្ត និងមានបម្រើសេវាម្ហូបអាហារដែលមានដាក់លក់ ឬបញ្ជាទិញជាច្រើនបែប។ ទោះបីជាមានសង្គ្រាមបំផ្លិចបំផ្លាញយ៉ាងណាក៏ដោយ ភ្នំឧត្តុង្គនៅមានសម្រស់ធម្មជាតិ និងទេសភាពល្អត្រកាល ជំនោរខ្យល់ល្អបរិសុទ្ធ ដែលអាចទាក់ទាញភ្ញៀវទេសចរជាតិ និងអន្តរជាតិបានយ៉ាងច្រើន។ ក្រៅពីគោលដៅទេសចរណ៍បែប វប្បធម៌ សាសនា និងប្រវត្តិសាស្ត្រហើយនោះ ឧដុង្គ ក៏ជាទីតាំងរបបប្រល័យពូជសាសន៍មួយដែរ។ នៅទីនេះមន្ទីរបូជនីយដ្ឋានធ្វើអំពីឥដ្ឋប្រក់ក្បឿងមួយកន្លែងរបស់ស្រុកពញាឮ បានត្រូវសាងសង់ឡើងក្បែរ ជើងភ្នំអដ្ឋរសហៅភ្នំឧដុង្គ។ មន្ទីរនេះមានដាក់តម្កល់អដ្ឋិធាតុយ៉ាងច្រើនដែលបានមកពីការជីកគាស់រណ្ដៅសាកសពកាលពីអំឡុងឆ្នាំ១៩៨០។ អដ្ឋិធាតុភាគច្រើន ត្រូវប្រជាជនជញ្ជូនមកពីទីតាំងសម្លាប់ចម្ការស្វាយ។ សាក្សីបានឱ្យការថា នៅទីតាំងនោះ មានជនរងគ្រោះត្រូវបានសម្លាប់ ចំនួនប្រហែល៧០០០ នាក់។ នៅឆ្នាំ២០០២ និង២០០៣កន្លងទៅ ក្រុមធ្វើកោសល្យវិច័យបានចុះមកកាន់ទីនេះ ដើម្បីសុំការអនុញ្ញាតិពិនិត្យឆ្អឹងលលាដ៏ក្បាលនិងឆ្អឹងអវៈយវៈដែលមានតម្កល់នៅក្នុងមន្ទីរបូជនីយដ្ឋានដ៏ធំនេះ។",
    "descriptionEn": "A brick-and-mortar sanctuary in Ponhea Leu district was built at the foot of Phnom Ethareus, also known as Phnom Odong. The sanctuary is used to hold a large number of remains from excavations during the 1980s. Most of the remains were transported from the slaughterhouse. Witnesses said about 7,000 victims were killed at the scene. In 2002 and 2003, autopsy teams visited the area to ask for permission to examine the skulls and limbs kept in this large sanctuary.",
