    "descriptionEn": "On a hill of the southeastern Phnom Artharos, which can be reached by getting through the entrance of Thom Ke Pagoda, there is a stupa of Preah Chan Reachea, a king who built the city of Longvek and continued the unfinished carving work in the south corner of Angkor Wat. Nearby are stone statues of a king’s foot and a temple that was bombed during the war.",
