    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ចេតិយធំទាំងបីនិងតូចៗមួយចំនួនទៀត ដែលស្ថិតនៅលើភ្នំជ្រុងខាងជើង ត្រូវបានហៅថា “ចេតិយត្រៃត្រិង្ស”។ ចេតិយទាំងនេះ តម្កល់អដ្ឋិធាតុក្សត្រាក្សត្រី ដែលជាព្រះរាជវង្សានុវង្សដែលអាចឡើងទៅដល់តាមផ្លូវទល់មុខវត្តពុទ្ធមណ្ឌលវិបស្សនាធុរៈសន្តិវ័ន។ ចេតិយទាំងនេះតម្កល់ធាតុព្រះរាជវង្សានុវង្សនៃព្រះនរោត្តមនិងព្រះស៊ីសុវត្ថិ ដែលតាមចេតិយនីមួយៗបានចារព្រះនាមជាសម្គាល់។ ក្រៅពីនេះក៏មានចេតិយបុរាណខ្លះទៀត ដែលមិនអាចកំណត់បាននៅតាមជើងភ្នំឧដុង្គ។",
    "descriptionEn": "The three large and some small stupas on the northern corner of the mountain are called the \"Trai Treung Stupa\". These stupas carry the remains of the royal family, which can be reached on the road in front of Wat Buddhi Mondul Vipassana Thurak Santivan. These stupas bear the relics of the royal family of Norodom and Sisowath, each inscribed with a name. Apart from this, there are some other ancient stupas that cannot be identified at the foothill of Udong mountain.",
