    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "នៅជិតព្រះសក្យមុនីចេតិយ ដែលទើបសង់ថ្មី មានចេតិយច្រើនទៀត ដែលតម្កល់អដ្ឋិធាតុព្រះរាជា សម័យមុន ហៅថាចេតិយទន្ទឹម។ ចេតិយខាងជើងមានឆ្លាក់រូបដំរី លេចក្បាលធ្លោ ឡើងប៉ុនដំរីមែនទែន គេហៅថា \"ចេតិយសាមពាន់\" ត្រូវបានកសាងឡើងតាំងពី គ្រិស្តសករាជ ១៦២៣ ដោយព្រះបាទជ័យជេដ្ឋា ដើម្បីបញ្ចុះព្រះបរមអដ្ឋិនៃ ព្រះបាទស្រីសុរិយោពណ៌ជាបិតា ជាប់គ្នាខាងត្បូង កសាងឡើងក្នុងគ្រិស្តសករាជ ១៨៩១ ដោយព្រះនរោត្តម ដើម្បីបញ្ចុះព្រះបរមអដ្ឋិព្រះអង្គឌួង ជាព្រះវររាជបិតា ចុះតាមជណ្ដើរថ្មទៅត្បូងបន្តិច គេនឹងឃើញចេតិយដ៏ធំមួយទៀត ដែលជាចេតិយ របស់ព្រះមុនីវង្ស មានក្បូរក្បាច់ហាក់ស្អាតបាតនៅឡើយ។",
    "descriptionEn": "Near the newly built Shakyamuni Stupa, there are many other stupas that hold the remains of the ancient kings called “Tontoem Stupa”. The northern stupa has a statue of an elephant with a prominent head like a real elephant, called \"Sam Poan Stupa\" was built since 1623 A.D. by the King Chey Chetha to bury the ashes of his father, the King Srei Soriyopor. Adjacent to the south, built in 1891 by the King Norodom to bury the remains of King Ang Duong, the King Father. Going down the stone stairs to the south, you will see another large stupa, the stupa of the King Monivong which beautiful carvings still remains.",
