    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តវិហារសំណ មិនត្រឹមតែមានប្រវត្តិព្រះវិហារដ៏យូរលង់ទេ ទីនោះក៏ល្បីមានចេតិយបុរាណហ៊ុមព័ទ្ធដោយរុក្ខជាតិតូចធំ និងដើមជ្រៃរយឆ្នាំដុះចាក់ឫសខ្វាត់ខ្វែងដ៏ខ្ពស់សន្លឹមផងដែរ។ រឿងនិទានតំណាលថា ជនជាតិចិនមួយក្រុមបានធ្វើដំណើរតាមផ្លូវទឹកដោយសំពៅមកដល់ភាគខាងជើងភ្នំព្រះរាជទ្រព្យ ស្រាប់តែសំពៅកឿងកល់ជាប់មួយកន្លែងទៅមុខពុំរួច ទើបជនជាតិចិនទាំងនោះបានធ្វើការបួងសួងម្ចាស់ទឹកម្ចាស់ដី សុំធ្វើដំណើរឲ្យមានសេចក្ដីសុខដោយរៀបចំគ្រឿងសក្ការបូជានិងពាក្យសន្យាសង់ព្រះវិហារថ្វាយ។ ទីបំផុតបារមីវត្ថុស័ក្ដិសិទ្ធិបានជួយឲ្យពួកគេសម្រេចបំណងមែន ទើបតាមការសន្យា ក្រុមជំនួញជនជាតិចិនបានត្រឡប់មកកសាងព្រះវិហារជញ្ជាំងរៀបឥដ្ឋ បូកបាយអ ដំបូលប្រក់សំណ សសរឈើក្រាក់បំពាក់ជហ្វាដងក្ដារក្បាច់រចនាសុទ្ធតែឈើទាំងអស់និងព្រះអង្គធំក្នុងព្រះវិហារធ្វើពីថ្មភក់ដោយព្រះភ្នែនទំហំ ២,៨ ម៉ែត្រតាមរចនាបថសម័យអង្គរ។ នៅក្នុងទីវត្តនេះ មានចេតិយបុរាណគេនាំគ្នាហៅតៗមកថា ចេតិយព្រះនាងកែវណាម៉ា ដែលមកទល់ពេលនេះគ្មាននរណា អះអាងលើសពីពាក្យត្រឹមថា «ចេតិយបុរាណ»តែប៉ុណ្ណោះ។ ដោយសារតែព្រះវិហារនេះប្រក់សុទ្ធតែលោហធាតុសំណទើបប្រជាជនដាក់ឈ្មោះថា «ព្រះវិហារសំណ»។ ព្រះគ្រូចៅអធិការតាំងពីឆ្នាំ ១៩៨៧ បានសម្ដែងការសោកស្ដាយដែលមិនអាចឃាត់ខាំងការខួងយកមាស និងសំណយ៉ាងគគ្រឹកគគ្រេងនាទសវត្សឆ្នាំ ១៩៩០ ហើយលោកបានវាយកម្ទេចអារាមទ្រុឌទ្រោមបុរាណដើម្បីសង់ព្រះវិហារថ្មីក្នុងឆ្នាំ ២០០០ ដោយមិនបានយកគម្រូប្លង់តាមព្រះវិហារចាស់ទៀត។ ប៉ុន្តែរូបចម្លាក់ព្រះពុទ្ធដ៏ធំក្នុងព្រះវិហារនោះ គឺជាចម្លាក់ដើមដោយគ្រាន់តែលាបពណ៌ពីលើ។",
    "descriptionEn": "Vihear Somnor pagoda not only has a long history of Buddhist temples, but it is also famous for its ancient stupas surrounded by small and large plants and hundreds of years old of banyan trees growing tall and lanky. Legend says long time ago, there was a group of Chinese who traveled by ship; unfortunately, the ship grounded at the northern of Preah Reach Troap mountain. The Chinese prayed to the lord of land and lord of water for their safety in traveling, so that they would build a Buddhist temple in return. Eventually, sacred power of lord helped them for their praying. As promised, those Chinese traders returned to build a big Buddhist temple. The wall of the temple was made of brick and mortar; the roof was made of lead; the pillars were made of wood, with wooden roof finials. And the big Buddha statue made of sandstone with the cross-leg 2.8 meters in the Angkorian style. In this pagoda, there is an ancient stupa, gradually called the stupa of Princess Keo Nama, which until now no one claims more than just the word \"ancient stupa\". Because this temple is made of lead metal, people named it Vihear Somnor (Lead Temple). Since 1987, the chief monk has expressed his regret that the illegal drilling of gold and lead in the 1990s could not be stopped. Later, he demolished an old monastery to build a new Buddhist temple in 2000 without following a sample of the old one. However, the big Buddha statue is an original sculpture, just with a new painting.",
