    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ទីវត្តបុរាណមួយដែលមានព្រះវិហារសង់លើខឿនថ្មបាយក្រៀមនៃប្រាសាទចាស់ និងមានចេតិយ៦សង់ពីឥដ្ឋ។ នៅពេលសព្វថ្ងៃ នេះ គេបានសង់វិហារថ្មី តែនៅមានសល់ចេតិយពីរមួយនៅល្អ មួយទៀតបែកបាក់ តែអាចយល់ទម្រង់បាន។ នៅក្នុងព្រះវិហារមានតម្កល់សិលាចារិក k112។ ទីតាំងនេះមានទាក់ទងនឹងព្រះរាជាដែលសោយរាជ្យនៅទួលបាសាន ហើយជាទីទួលដែលអាចសង់ចេតិយដាក់អដ្ឋិធាតុ ព្រោះនៅទួលបាសានមានទឹកជំនន់ទន្លេមេគង្គលិចជារៀងរាល់ឆ្នាំ ទើបត្រូវយកអដ្ឋិធាតុមកបញ្ចុះនៅទីនេះ។ តាមរយៈអាយុកាលនេះចេតិយគួរត្រូវបានសាងសង់នៅរវាងចុងសតវត្សទី១៦ និងដើមសតវត្សទី១៧។",
    "descriptionEn": "It is an ancient pagoda with a Buddhist temple built on the laterite platform of the old temple and six stupas built of brick. Nowadays, a new Buddhist temple has been built; however, only two stupas remain; one is with good condition and another one is broken, but it is shape-known. In the Buddhist temple, there is inscription K112. The location is related to a king who reigned at Tuol Basan and it is also the hill that can be used to build a stupa because the Mekong River floods every year at this site which is the reason to bury the remains here.",
