    "descriptionEn": "Phnom Pon natural resort is located closely to the beach convenient for tourists to enjoy the view of the sea and screen scenic images of surrounding nature. The resort is reach in natural scenery, beautiful forests and beaches. Inside the pagoda, there is a Buddha statue called Vittakamutra (ទ្រង់វិតក៌មុទ្រា). He uses his right middle finger to connect with his thumb to form a circle, and places the right hand on his thight.",
