    "descriptionEn": "Rabbit island is a natural resort located at the south-east of Krong Kep. Rabbit island is a natural resort with two beaches, ideal for swimming with beautiful sea views. Tourists can reach the destination by boats. Rabbit island is an island among the 13 islands in Kep province, The most interesting scenery of the island is the lush plantation and breeze and cool weather. On the white sand beach, tourists are relaxed with the sound of water crashing the riff and the eye-catching view of the seaside. Establishing a community on Rabbit Island really makes the local people’s living standard more improved through various advantages they get from providing food and guesthouse services to international tourists. Up to the present, the numbers of international tourists are increasing remarkably. The room and board service are affordable.",
