    "descriptionKh": "ក្នុងទ្រង់ទ្រាយជាឆ្នេរនេសាទ ឆ្នេរអង្កោលបង្ហាញនូវសម្រស់ទាក់ភ្នែកមួយបែប ប្រកបដោយឆ្នេរខ្សាច់ពណ៌ស្ករត្នោតនិងដើម ដូងដុះរៀងតាមឆ្នេរ។ ឆ្នេរខ្សាច់ពណ៌ស្ករត្នោតប្រវែង ៣០០ ម៉ែត្រក្រាលភ្ជាប់វាលស្មៅបៃតងខ្ចីអមដោយព្រៃដូងរាប់រយដើមដុះរៀងតាមឆ្នេរ ជាទីឋានលម្ហែគយគន់ផ្ទៃសាគរឆ្ងាយដាច់កន្ទុយភ្នែក និងស្រូបយកខ្យល់អាកាសបរិសុទ្ធនៃជំនោរសមុទ្រ។ ទីនេះស័ក្ដិសមសម្រាប់ការបោះជំរំតង់ស្នាក់អាស្រ័យ ការសម្រាកសម្រាន្តនិងថតរូបដ៏ពេញនិយម។ ក្យូសជាច្រើនត្រូវបានសង់ជាជម្រកសម្រាប់ភ្ញៀវទទួលទានអាហារគ្រឿងសមុទ្រពីប្រជានេសាទសហគមន៍ស្រង់ឡើងពីទឹកថ្មីៗ និងស្រស់។",
    "descriptionEn": "In the form of a fishing beach, Angkoal beach shows an eye-catching beauty with brown sand and coconut trees growing along the beach. The 300-meter-long brown sandy beach is lined with lush green meadows, hundreds of coconut trees, along the beach as a place to relax, and sightsee the view of the sea as far as the eyes can see, and breathe-take the fresh sea breeze. Many kiosks are constructed for tourists to rest for their meal which are mostly fresh and delicious seafood bought from the community fishermen.",
