    "id": "rac-k03007",
    "nameKh": "ភ្នំវល្លិ៍",
    "nameEn": "Voir Mountain",
    "categorySlug": "mountain",
    "categoryKh": "ភ្នំ & ឧទ្យានជាតិ",
    "categoryEn": "Mountains & National Parks",
    "descriptionKh": "ភ្នំវល្លិ៍ជាអតីតទីតាំងយុទ្ធសាស្រ្តយោធាដ៏រឹងមាំមួយរបស់ក្រុមខ្មែរក្រហមនៅភាគនិរតីប្រទេស ដែលបច្ចប្បន្នបានក្លាយជាតំបន់កសិទេសចរណ៍ដ៏គួរឱ្យចាប់អារម្មណ៍។ ទីនេះមានប្រវត្តិអតីតមេបញ្ជាការខ្មែរក្រហមឈ្មោះ ឈូក រិន បានបញ្ជាឱ្យបាញ់សម្លាប់ចំណាប់ខ្មាំងបរទេស៣នាក់ ក្នុងនោះមាន ជនជាតិស្ត្រាលី បារាំង និងអង់គ្លេសនៅទីនោះ។ តំបន់ភ្នំវល្លិ៍បានប្រែក្លាយជាតំបន់អភិវឌ្ឍន៍ សម្បូរដោយចំការម្រេច និងដំណាំផ្សេងៗច្រើនបែប។ តំបន់នេះមានសេវាស្នាក់នៅច្រើនប្រភេទ តាំងពី បោះតង់ ផ្ទះសំណាក់ បឹងកាឡូ រហូតដល់សណ្ឋាគារនាជើងភ្នំប្រកបដោយអាងហែលទឹកជាដើម។ រមណីយជ្រលងភ្នំក្រហម ជាទីតាំងមួយក្នុងចំណោមទីតាំងជាច្រើនទាំងនេះ ដែលទេសចរអាចជិះកង់ អុំទូក ហែលទឹក ឬជិះត្រាក់ទ័រ សណ្ដោងរ៉ឺម៉ក និងមានសេវាម្ហូបអាហារដោយតម្លៃសមរម្យ។ ភ្ញៀវក៏មានជម្រើសផ្សេងទៀត គឺនៅលើភ្នំកូនសត្វជិតនោះ មានរមណីយដ្ឋានសម្រាកលំហែកាយដ៏ប្រណិត បែបសណ្ឋាគារផ្កាយបីមានអាងហែលទឹកបន្តុបលើចង្កេះភ្នំ ប្រកបដោយទេសភាពស្ងប់ស្ងាត់បែបជនបទ អាចហែលទឹកពណ៌ខៀវស្រងាត់និងគយគន់ជួរភ្នំកូនសត្វព្រមទាំងជួរភ្នំវល្លិដ៏អន្លាយសន្លឹម។",
    "descriptionEn": "Phnom Voir was once a strong strategic Khmer Rouge stronghold in the southwest of the country, which has now become an attractive agro-tourism destination. This area is a place where a former Khmer Rouge commander, Chhouk Rin, ordered the shooting death of three foreign hostages: Australians, French and British nationals. Phnom Voir has become a development area rich in pepper plantations and various plantation. The area offers a variety of accommodation services, from tents, guesthouses, bungalows to hotels at the foot of the mountain with a swimming pool. Red Valley Resort is one of the many places where tourists can enjoy biking, boating, swimming or taking tractor, riding tuk tuk and get affordable food service. Tourists also have other options to explore as on Phnom Kon Sat nearby where there is a luxurious resort consists of a three-star hotel with a swimming pool perched on a hillside with a quiet countryside view of the lush greenery. Tourists are able to enjoy swimming and soul-attract by the scenic green mountain view Phnom Kon Sat and Phnom Voir.",
