    "descriptionKh": "នៅតាមបណ្ដោយផ្លូវឆ្ពោះទៅកាន់ភ្នំវល្លិ៍ ព្រះវិហារធ្វើពីស៊ីម៉ង់តដ៏ធំមួយនៅវត្តកំពង់ត្រឡាច ភូមិ កំពង់ត្រឡាច ឃុំកែប ស្រុកកំពត ត្រូវបានប្រើប្រាស់ជាមន្ទីរសន្តិសុខកាលពីជំនាន់ខ្មែរក្រហម។ អ្នកទោស ដែលជាប់នៅក្នុងមន្ទីរសន្តិសុខនេះ ត្រូវខ្មែរក្រហមនាំយកទៅសម្លាប់នៅក្នុងរណ្ដៅធំៗចំនួនពីរក្នុងបរិវេណវត្ត និងនៅកន្លែងផេ្សងទៀត ដែលមានចម្ងាយប្រហែល២គីឡូម៉ែត្រពីវត្ត។ នៅឆ្នាំ១៩៧៩ រណ្ដៅសាក សពទាំងនោះត្រូវបានគាស់ ហើយអដ្ឋិធាតុត្រូវនាំយកមកដាក់តម្កល់នៅក្នុងមន្ទីរបូជនីយដ្ឋានមួយដែលសង់ ផ្ទាល់ដីពីស៊ីម៉ងតប្រក់ក្បឿងនាបរិវេណវត្តកំពង់ត្រឡាច។ សាក្សីរៀបរាប់ថា មានឆ្អឹងលលាដ៏ក្បាល ទាំងអស់ចំនួន៧៥០ និងឆ្អឹងអវៈយវៈជាច្រើនទៀត ត្រូវបានប្រជាជនដឹកជញ្ជូនមកកាន់មន្ទីរបូជនីយដ្ឋាន នេះកាលពីឆ្នាំ១៩៧៩។",
    "descriptionEn": "Along the road to Phnom Voir, there is a large concrete Buddhist temple at Kampong Trolach pagoda, Kampong Trolach village, Kep commune, Kampot district, was used as a security center during the Khmer Rouge era. The prisoners from this security center were taken to be killed in two large pits inside the pagoda and elsewhere, about two kilometers from the pagoda. In 1979, the graves were exhumed and the remains were taken to a shrine built with tilt rood on the ground floor in Kampong Trolach pagoda. Witnesses say 750 skulls and other limbs were transported to the shrine in 1979.",
