    "descriptionEn": "Peam Krasop in Koh Kong is one of the largest mangrove forests in the province that should not be missed. At the beginning of the dry season, tourists can take a boat trip to see the sea, especially with houses in the mangrove forest. Boat trips along the offshore canals between December and January are likely to have dolphins visible to visitors. From Kayak Lake, there are small and large fishing boats and fishermen's floating houses, and a small island in the middle of the lake, where the community has small stalls to accommodate tourists to relax and enjoy the natural look.",
