    "descriptionKh": "ឆ្នេរនេសាទមានឆ្នេរខ្សាច់សអមដោយដូងជ្រំ តាមបណ្ដោយឆ្នេរ ដែលប៉ុន្មានឆ្នាំចុងក្រោយឆ្នេរនេសាទបានទទួលភ្ញៀវទេសចររឹតតែច្រើនឡើងៗ។ ឆ្នេរនេសាទមានសភាពល្អ និងមានសក្ដានុពលទាក់ទាញភ្ញៀវទេសចរច្រើន ប៉ុន្តែសហគមន៍នៅខ្វះសេវាកម្មស្នាក់នៅនិងម្ហូបអាហារព្រមទាំងបញ្ហាបរិស្ថាននៅជុំវិញឆ្នេរ។ សក្ដានុពលចម្បងគឺឆ្នេរខ្សាច់សស្អាតប្រវែង ៣,៥ គីឡូម៉ែត្រ ព្រៃកោងកាង និងអាហារគ្រឿងសមុទ្រដែលភ្ញៀវទេសចរចាប់អារម្មណ៍ជាខ្លាំង ប៉ុន្តែកត្តាបរិស្ថានស្អាតគឺជាកត្តាចំបងដែលគួរគិតគូរ។",
    "descriptionEn": "Chroy Svay Beach or Fishing Beach has a white sand beach with coconut trees along the beach. The fishing beaches are good and have the potential to attract a lot of tourists, but the community still lacks accommodation and food services, as well as environmental issues around the beach. The main potential is the 3.5 km long white sand beach, mangrove forest and seafood which are of great interest to tourists, but the own environmental factors are the main factors to consider.",
