    "id": "rac-k04015",
    "nameKh": "ព្រៃកោងកាងពាមក្រសោប",
    "nameEn": "Boeung Kayak Mangrove Forest",
    "categorySlug": "nature",
    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "រមណីយដ្ឋានព្រៃកោងកាង ប៉ាងកាយាក គឺជារមណីយដ្ឋានមួយមានផ្ទៃក្រឡា ៥.២០០ ហិកតា។ នៅទីនោះគេបានធ្វើស្ពានថ្មើរជើងបេតុងតូចមួយប្រវែង ជាង ៦០០ម៉ែត្រ នាំយើងដើរទស្សនាតំបន់ទេសចរណ៍ធម្មជាតិព្រៃកោងកាង។ នៅឯចុងស្ពាននេះមានស្ពានយោលមួយដែលចម្លងយើងទៅដល់ប្រាង្គមួយកម្ពស់ ១៥ម៉ែត្រ សម្រាប់ទស្សនាសម្រស់ធម្មជាតិព្រៃកោងកាង និងដងអូរនានាក្នុងតំបន់នោះ។ បើសិនជាភ្ញៀវមានបំណងចង់ជិះទូកកម្សាន្ត ទៅតំបន់ពាមក្រសោប គេអាចរកសេវានេះបាននៅទីនេះ។ ម៉្យាងវិញទៀត យើងអាចចាប់អារម្មណ៍និងធនាគារក្ដាម ដែលជាទម្រង់ពិសេសមួយក្នុងការរក្សានិរន្តរភាពនៃធនធានសមុទ្រ។ នៅក្នុងរមណីយដ្ឋានក៏មានលក់ចំណីអាហារ ហើយក៏មានភោជនីយដ្ឋានសមរម្យ ដែលអាចហូបអាហារនៅទីនោះក៏បាន។ នៅរដូវប្រាំងនាពេលរាត្រីគេអាចមើលពន្លឺអំពិលអំពែកហាក់បីដូចហ្វូងតារារយពាន់នៅក្នុងព្រៃនេះដែរ។",
    "descriptionEn": "Boeung Kayak Mangrove Forest Vacation Resort is an area of ​​5,200 hectares. There they built a small concrete pedestrian bridge over 600 meters long to take us for a ride through the mangrove forest. At the end of the bridge there is a swing bridge that crosses us to a 15 meter high tower to see the natural beauty of the area's mangrove forests and streams. If tourists want to take a boat trip to Peam Krasop, they can find this service here. On the other hand, we can be interested in the banks of crabs, which are a particular form of sustainability of marine resources. The resort also sells food and there are some good restaurants where you can dine. During the dry season, at night, you can see the light of the tamarind, like a hundred thousand stars in this forest.",
