    "descriptionEn": "Ji Phat Ecotourism Area In addition to high waterfalls and Chhay Chrey, the area has many natural attractions such as ancient tombs, which are about 500 years old, ancient jars, sunset observation sun from the top of the mountain, lobster fishing at night, tamarind watching Take a boat trip by the sea, watch the sunrise, bat caves, water streams , Cardamom Streams, Orange Groves, Silver Streams, Golden Fields, Golden Ponds, Ponds, Bad Lakes, Mountains, etc. and rainforest sanctuary in Southeast Asia. . Chiphat is considered by the Ministry of Tourism as the most attractive ecotourism site in Cambodia after Areng.",
