    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "រមណីយដ្ឋានចេតិយឃុនឆាងជាកន្លែងទាក់ទាញភ្ញៀវទេសចរទៅទស្សនាញឹកញាប់ជាងគេក្នុងខេត្តកោះកុង ព្រោះស្ថិតនៅជិតទីរួមខេត្ត។ ឃុនឆាងឃុនផែន ជាប្រវត្តិនៃស្នេហាត្រីកោណរវាងឃុនឆាង ឃុនផែន និងនាងភឹម ដោយឃុនឆាងមានរូបរាងមិនស្អាតទេ គឺគាត់ក្បាលទំពែក ប៉ុន្តែជាកូនអ្នកមានបានទៅដណ្ដឹងយកនាងភឹមធ្វើ ជាប្រពន្ធ។ ប៉ុន្តែនាងភឹម ដែលមានសង្សារឈ្មោះ ឃុនផែន កំពុងធ្វើជាកងទ័ព បានសុខចិត្តរៀបការ បំពេញមុខឪពុកម្ដាយហើយក៏បានផិតប្ដីទៅទាក់ទងជាមួយសង្សារចាស់ រហូតឃុនឆាង ដឹងក៏បានយករឿងទៅប្ដឹងស្តេច។ ពេលនោះស្តេចបានកាត់ក្ដីឱ្យពុះនាងភឹមជាពីរចំណែកចែកគ្នា។ ក្រោយមកឃុនឆាង បានយកសាកសពនាងទៅកប់នៅទីកន្លែងនោះដោយស្អប់និងខឹងនាងពេកថាជាស្រីក្បត់។ ប៉ុន្តែគាត់ក៏ចង់ឱ្យនាងឆាប់ចាប់កំណើតជាថ្មី ក៏យកទង់ព្រលឹងមកចងនៅត្រើយខាងកើតនៃដងព្រែកនោះឱ្យទល់មុខគ្នានឹងកន្លែងបញ្ចុះសព ហើយបានកសាងចេតិយមួយទុកជាអនុស្សាវរីយ៍ ទើបនៅត្រើយខាងលិចក៏មានឈ្មោះថាភូមិចេតិយ និងត្រើយខាងកើតក៏មានឈ្មោះថាភូមិដងទង់ រហូតដល់បច្ចុប្បន្ននេះ។",
    "descriptionEn": "Khun Chhang Stupa Holiday Resort is the most frequent tourist attraction of Koh Kong province as it is close to the provincial town. Khun Chhang Khun Phen is the story of the love triangle between Khun Chhang Khun Phen and Neang Phim. But Phim, who has a girlfriend named Khun Phen who is in the military, agreed to marry in front of his parents and also committed adultery with his ex-girlfriend until Khun Chhang found out and carried the case before the king. At this time, the king decided to divide Phim into two parts. Later, Khun Chhang buried her body there, hating her and angry at her for being a traitor. But he also wanted her to be reborn soon, so he tied the soul flag on the east bank of the canal to face the cemetery, and built a memorial stupa on the west bank. The stupa village and the east coast are also called Dang Tong village until today.",
