    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តអង្គរភ្នំខ្លុង សិ្ថតនៅតាមបណ្ដោយព្រែកស្រែអំបិលមានសំណល់គំនរថ្មបាយក្រៀម ដែលមានការយល់ច្រឡំថាជាប្រាសាទសម័យអង្គរ។ សណ្ឋានប្រាសាទជាចេតិយនៅលើទីតាំងប្រាសាទចាស់ ដោយទីតាំងនោះមានជាកំពែងសាងពីថ្មបាយក្រៀមព័ទ្ធជុំវិញ។ ថ្មបាយក្រៀមជាកំពែងនោះមានទំហំធំៗ ស្រដៀងទៅនឹងថ្មបាយក្រៀមជាកំពែងប្រាសាទនៅសម័យអង្គរ ដែលថ្មនោះ គួរតែជាថ្មនៅលើភ្នំនេះតែម្ដង ព្រោះនៅក្បែរនោះក៏ឃើញមានថ្មបាយក្រៀមធម្មជាតិផងដែរ។ សំណល់គំនរថ្មមានសណ្ឋានជាចេតិយរាង៨ជ្រុង ហើយមានខឿនខាងក្រោមរាងបួនជ្រុងមិនមានក្បាច់លម្អនោះទេ ដែលប្រហែលជាសាងឡើងនៅសម័យកណ្ដាល។ ហួសពីទីនោះប្រហែល ៥០ម៉ែត្រ មានជាចេតិយមួយទៀត ដែលមានទំហំប្រហាក់ប្រហែលនឹងចេតិយមុនដែរ។",
    "descriptionEn": "Angkor Phnom Khlong Pagoda is located along the Sre Ambel Canal, with laterite remains that are mistaken for Angkorian temples. The structure of the temple is a stupa on the site of the ancient temple, which is surrounded by a laterite wall. The laterite is large, similar to the laterite of the temples of the Angkorian period, which should be the stone of this mountain, because there is also natural laterite nearby. The remains of the piles have the shape of an octagonal stupa, with a quadrangular base, without ornament, probably dating from the Middle Ages. About 50 meters further there is another stupa which is about the same size as the previous one.",
