    "descriptionKh": "ខុសពីប្រាសាទល្បើកស្រុតដែលនៅតំបន់ជាមួយគ្នានោះ ប្រាសាទនេះនៅមានរូបរាងនៅសល់ខ្លះ រួមមានប្រាង្គមួយធ្វើពីឥដ្ឋប្រកបដោយក្បូរក្បាច់រចនាដ៏រស់រវើកមានរចនាបថសំបូរ ថ្វីត្បិតតែមានការជីកគាស់កកាយហើយមែន។ សំណល់មេទ្វារមួយធ្វើពីថ្មភក់នៅអែបជញ្ជាំងឥដ្ឋ ដែលនៅសល់ក្រោយពីដំបូលបានរលំបាក់បែកអស់។ ចំណែកសសរពេជ្រនិងផ្ដែរបាត់បង់អស់។ ប្រាសាទមានរាងចតុកោណកែងសង់លើខឿនថ្មបាយក្រៀម មានប្រាង្គបីសង់ពីឥដ្ឋរត់ជួរជើងត្បូង បែរមុខទៅកើត និងមានទ្វារបញ្ឆោតបីតាមទិសផ្សេងទៀត។ សព្វថ្ងៃនេះប្រាង្គសងខាងបានរលំបាក់អស់ សល់តែប្រាង្គកណ្ដាលដែលមានរូបរាងជញ្ជាំងនិងបំណែកគ្រឿងលំអផ្សេងៗ។ តាមសិលាចារឹកមួយផ្ទាំងត្រូវបានរកឃើញនៅទីនេះ មានលេខ K. 121 ហើយចារឹកក្នុងឆ្នាំ៧១៦ គ.ស។",
    "descriptionEn": "Unlike the collapsed temple in the same area, the temple still has some remains, including a cartoonish brick tower, rich in style despite excavation. Remains of a sandstone doorknob on a brick wall left behind by a collapsed roof. Diamond pillars will be lost. The temple is rectangular in shape, built on laterite, with three brick towers facing south and three false doors in the other direction. Today, both sides of the tower have collapsed, leaving only the central tower, which is shaped like a wall, and other decorative pieces. According to an inscription found here, the number K. 121 and inscribed in the year 716 AD.",
