    "nameKh": "ប្រាសាទបន្ទាយសៀមកាត់សក់, ប្រាសាទបន្ទាយសៀម",
    "nameEn": "Banteay Siem Kat Sak Temple",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទបន្ទាយសៀម ឬបន្ទាយសៀមកាត់សក់ កសាងឡើងអំពីថ្មបាយក្រៀម ក្នុងរជ្ជកាលស្តេច៣ព្រះអង្គ នៅសម្ភុបុរ (ព្រះនាងនីពេន្រ្ទទេវី, ព្រះនាងជេស្ថារ្យ, ព្រះនាងជយេន្រ្ទភា)។ ប្រាសាទនេះខូចខាតជាទម្ងន់ដោយតួប្រាសាទទាំងមូលបានខូចខាតដោយសារការជីកកកាយរបស់មនុស្ស។ ទោះបីជាតួប្រាសាទត្រូវបានខូចខាតទាំងស្រុង តែប្រាសាទនេះ នៅសេសសល់កំពែងថ្មធ្វើពីថ្មបាយក្រៀមព័ទ្ធជុំវិញផងដែរ។ គេសង្កេតឃើញមានសេសសល់នូវសំណល់ផ្ដែរ១ ដែលមានរចនាបថកំពង់ព្រះ ដែលមានបណ្ដោយ២១៤សង់ទីម៉ែត្រ ទទឹង ៨.៥សង់ទីម៉ែត្រ និងកម្ពស់ ១៩សង់ទីម៉ែត្រ។ ស៊ុមទ្វារចំនួនបួន ដែលស៊ុមមួយមានសិលាចារឹកចំនួន១បន្ទាត់កន្លះ គល់សរសរពេជ្រចំនួន៣ដុំ មានជើងទម្រពីរ និងឥដ្ឋទំហំធំៗមួយចំនួន។ ប្រាសាទស្ថិតនៅក្នុងព្រៃឡង់ មិនងាយនឹងធ្វើដំណើរទៅដល់ឡើយ។ បើខែវស្សាគឺត្រូវដើរ ចំណែកខែប្រាំង អាចជិះម៉ូតូបាន ដោយត្រូវចុះបណ្ដើរខ្លះៗផង។",
    "descriptionEn": "Banteay Siem Temple or Banteay Siam Kat Sok was built in laterite during the reign of three kings in Sambopura (Princess Nipentevi, Princess Jesthar, Princess Jayantaphea). The temple was badly damaged, with the entire body being damaged by human excavations. Although the temple was completely damaged, it is still surrounded by laterite walls. A remnant of the Kampong Preah style was observed to be 214 cm long, 8.5 cm wide and 19 cm high. Four door frames, a frame with an inscription, a line and a half, three diamond-shaped pillars, two pedestals and some large bricks. The temple is in Prey Lang, not easily accessible. If it rains you have to walk, while in the dry season you can ride a motorbike with some walking.",
