    "descriptionEn": "A creek with clear waters in the dry season, accompanied by a beautiful landscape of forests on both sides of the creek and a row of bamboo trees at the top of the creek is a beautiful resort called Prek Ta Prum. Tourists come to visit here only in the dry season, because in the rainy season there are floods and cannot visit. Tourists can relax, have lunch with family and swim in the clear water. It is a great place to relax during the dry season, especially during the traditional Khmer New Year and Chinese New Year, but the road is rough with room for cars.",
