    "descriptionEn": "Kampi Holiday Resort is a naturally attractive place located along the Mekong River near Kampi Dolphin Canyon. Kampi is a small archipelago with beautiful sand, shallow waters where tourists can snorkel and swim before eating in the long huts built in rows along the river. Kampi is a seasonal resort which tourists can only enjoy during the dry season from January to June. The most popular specialty here is the Chak Chreng, a long-tailed snail that lives only in Kampi and large fish like crows, buffaloes and scorpions. The place is organized and managed by the community.",
