    "categoryKh": "រមណីយដ្ឋានធម្មជាតិ & កែច្នៃ",
    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "កាំពីជាឈ្មោះភូមិមួយដែលមានទីតាំងខាងកើតច្រាំងទន្លេមេគង្គខាងជើងក្រុងក្រចេះ។ ក្រៅពីរមណីយដ្ឋានកាំពីដ៏ល្បីល្បាញ ទីនេះក៏កន្លែងល្អនិងនៅជិតបំផុតពីរាជធានីដែលអាចទស្សនាផ្សោតទន្លេមេគង្គដ៏កម្រ។ អន្លង់ផ្សោតកាំពីជាអន្លង់ដែលមានផ្សោតរស់នៅប្រហែល២០ក្បាល។ តំបន់ផ្សោតកាំពីត្រូវបានបង្កើតឡើងក្នុងឆ្នាំ១៩៩៩ ដើម្បីស្វាគមន៍ភ្ញៀវទេសចរអន្តរជាតិនិងក្នុងស្រុក និងអ្នកស្រាវជ្រាវវិទ្យាសាស្ត្រផងដែរ។ ផ្សោតទឹកសាប ជាថនិកសត្វកម្របំផុតនៅក្នុងពិភពលោក ដែលនៅអន្លង់ផ្សោតនេះមានសេវាកម្មទូកម៉ាស៊ីនសម្រាប់ដឹកភ្ញៀវទេសចរទៅទស្សនាផ្សោតបានជិតបំផុត។ ពេលវេលាល្អបំផុតដើម្បីទស្សនាផ្សោតគឺក្នុងរដូវប្រាំងនាពេលព្រឹកព្រលឹមនិងពេលល្ងាច។ ទោះបីជាផ្សោតផ្លាស់ប្ដូរជម្រកពីកន្លែងមួយទៅកន្លែងមួយទៀតតាមរដូវក៏ដោយ ប៉ុន្តែអ្នកបើកទូកម៉ាស៊ីនដឹងយ៉ាងច្បាស់ថាពួកវាប្ដូរទៅរស់នៅទីណា។ នៅតំបន់ផ្សោតកាំពីក៏មានលក់ចំណីអាហារ ភេសជ្ជៈ អាហារពិសាកម្សាន្ត វត្ថុអនុស្សាវរីយ៍ដូចជារូបភាព និងចម្លាក់ផ្សោតឈើដែលជាស្នាដៃសមាជិកសហគមន៍ក្នុងតំបន់។",
    "descriptionEn": "Kampi is the name of a village located on the east bank of the Mekong River north of the town of Kratie. Besides the famous resort of Kampi, it is also a good place and the closest to the capital to visit the rare Mekong dolphins. Dolphin Canyon Kampi is a canyon inhabited by about twenty dolphins. Kampi Region was created in 1999 to welcome international and local tourists as well as scientific researchers. Freshwater dolphins are one of the rarest mammals in the world. The best time to visit the dolphins is during the dry season, early morning and evening. Although dolphins move from place to place with the seasons, motorboat operators know exactly where they are moving. The Kampi area also sells food, drinks, snacks, souvenirs such as photos and wooden dolphin sculptures made by members of the local community.",
