    "descriptionEn": "A boat trip to the Virgin Islands, tourists can admire the landscape of rivers, archipelagos, sands and plants with strong roots to resist the force of water and many rare animals such as dolphins, deer . The island has beautiful white sand beaches like pristine vultures ruled by “Chroy Banteay Virgin Ecotourism community”. In addition to boating, tourists can also go fishing, camping on the island, and many other tourist activities. This natural island in the middle of the Mekong River was originally called \"Koh Yai\" and was later renamed \"Virgin Island\".",
