    "categoryEn": "Nature & Waterfalls",
    "descriptionKh": "ភ្ញៀវទេសចរទីជិតឆ្ងាយកម្រទៅដល់តំបន់សហគមន៍ទេសចរណ៍ធម្មជាតិមួយនេះ។ ទីនេះមានទេសភាពស្រស់បំព្រង ដែលមានទឹកទន្លេមេគង្គត្រជាក់ស្រេង ថ្លាឆ្វង់អាចឆ្លុះមុខបាន ហូរខ្មួលខ្មាញ់ប្រដេញលេងនឹងផ្ទាំងថ្មផុសពីបាតទន្លេនិងលាយឡំដោយរុក្ខជាតិតូចធំពណ៌បៃតងខ្ចី។ ស្ថានភាពផ្លូវចូលលំបាកជាឧបសគ្គសម្រាប់ដំណើរកម្សាន្តរបស់ភ្ញៀវ ដែលតំបន់ទេសចរណ៍ធម្មជាតិថ្មីដ៏កម្រនោះត្រូវបានសហគមន៍ដាក់ឈ្មោះថា «សហគមន៍ទេសចរណ៍ទឹកជួរតាចោរក្រហម ក» ដែលសូម្បីតែឈ្មោះក៏សឹងតែមិនដែលឮផង។ ពេលទេសចរបានទៅដល់តំបន់នេះធានាថា ពិតជាមានការជក់ចិត្តដិតអារម្មណ៍មិនខាន និងចង់ទៅចុះងូតកម្សាន្តឱ្យត្រជាក់កាយភ្លាមៗតែម្ដង។ ទេសភាពទឹកហូរកាត់លើថ្មរដិបរដុប អាចចុះងូតត្រាំ និងវាលខ្សាច់សក្បុសជាទីទាក់អារម្មណ៍ទេសចរ។",
    "descriptionEn": "Nearby tourists rarely visit this ecotourism community. It is a beautiful place where the water of the Mekong River is cold, the water is clear and crystal clear, you can see the face, the water is flowing, you can play with the rocks emerging from the bottom of the river and mixed with small and large green plants. Difficult access roads are a hindrance for visitors, and the rare new ecotourism area has been dubbed the \"red thief's water community\" by the community, which is almost unheard of. When tourists come to this area, it is guaranteed that they will be really excited and want to take a bath to refresh immediately. The landscape of water flowing through the rough rocks can be bathed, and the white desert is a tourist attraction.",
