    "descriptionEn": "Visitors can see the natural landscape of the river in the dry season from afar, clear, see the face of small and large plants, lush green leaves growing on the banks, rocks and bumps mixed with the landscape of the islands. The island is about 40 km long and almost 2 km wide. The Koh Pdao ecotourism community consists of four villages: Samphin, Koh Pdao, Kampong Krabei and Ampil Teuk. Most people here are engaged in fishing and agriculture, grow vegetables and vegetables at home, raise small animals in families. A special attraction for tourists is to see the dolphins and see the rare seasonal birds. They can learn about people's lives by also staying several days in the village. There are 17 hosting services. As for food, tourists can eat according to village tradition or can order in advance as the island has no market and is far from the mainland.",
