    "descriptionEn": "An ecotourism site that stretches along the upper Mekong between the provinces of Kratie and Stung Treng is a vast archipelago located in three villages: Khsach, Laos, Koh Khnhe and Poun Chea. Created in 2018, it is made up of many small and large islands, covered with small and large forests, and a set of Mekong watersheds and biodiversity. During the trip to the Thirty Islands, domestic and international tourists spend more than an hour on community boats along the Mekong River between the islands, admiring the beauty of the flooded forest, watching the sunset and sunrise, and photographing landscapes. endangered birds. On the white sand beach. The island can only be visited during the low water season, when the beautiful beaches rise and see the flooded forest, which is home to many rare species of fish and a total of 218 species of birds. Endangered.",
