    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "មន្ទីរវប្បធម៌ខេត្តក្រចេះ គ្រោងរៀបចំផ្ទះសសរ ១០០ ធ្វើជាសារមន្ទីរខេត្តនៅពេលខាងមុខ។ កន្លងមកមន្ទីរបានធ្វើការប្រមូលវត្ថុបុរាណពីវត្តចំណាស់ៗជាច្រើននិងវត្ថុបុរាណដែលបានបាក់បែកពីទីទួលប្រាសាទនានា ដែលមានអាយុកាលរាប់រយឆ្នាំ យកមករក្សាទុកនៅមន្ទីរវប្បធម៌និងវិចិត្រសិល្បៈខេត្តដើម្បីដាក់តាំងបង្ហាញជូនភ្ញៀវទេសចរជាតិនិងអន្តរជាតិបានចូលទស្សនា។ ចំណែកផ្ទះសសរ១០០ មានអាយុកាលជាង ២០០ ឆ្នាំ ដែលពីអតីតស្ថិតនៅភូមិកណ្ដុរ ឃុំឆ្លូង ស្រុកឆ្លូង ខេត្តក្រចេះ ត្រូវបានរុះរើនៅឆ្នាំ២០២០ យកមកសាងសង់ឡើងវិញ នៅក្នុងបរិវេណខាងលិចវិហារបុរាណវត្តរកាកណ្ដាល។ ទីនេះក្លាយជាទីតាំងបន្ថែមថ្មីលើឃ្លាំងមន្ទីរវប្បធម៌ខេត្តចាស់បន្ទាប់ពីការតាំងពិព័រណ៍ផ្ទះសសរ១០០ចប់ ហើយដែលមន្ទីរវប្បធម៌ខេត្តនឹងបញ្ជូនវត្ថុបុរាណខ្លះៗទៅដាក់នៅទីនោះ។",
    "descriptionEn": "The Provincial Department of Culture in Kratie has collected artifacts from many ancient pagodas and ruined artifacts from the hillside temples that are hundreds of years old and stored in the provincial museum for display to domestic and international tourists. The 100-pillar house, over 200 years old, once located in Kandor village, Chhlong township, Chhlong district, Kratie province, was demolished in 2020 and rebuilt in the area west of the ancient pagoda of Roka Kandal Pagoda.",
