    "id": "rac-k05018",
    "nameKh": "ព្រះវិហារចាស់វត្តរកាកណ្ដាល",
    "nameEn": "Ancient Temple of PagodaRoka Kandal",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "វត្តរកាកណ្ដាលចាស់ សាងសង់នៅក្នុងសតវត្សទី ១៨ ដែលមានព្រះវិហារឈើបុរាណ ចំណាស់ប្រមាណជាង២០០ឆ្នាំ ជាទីដែលទេសចរជាតិនិងអន្តរជាតិមិនគួររំលង។ ព្រះវិហារឈើបុរាណនេះ ដែលបានជួសជុលឡើងវិញរួចនេះ មានរំលេចទៅដោយ ក្បាច់ក្បូរយ៉ាងវិចិត្រធ្វើឡើងពីឈើគ្រញូង និងតាត្រាវ ជាពិសេស ក្បាច់ផ្កាភ្ញីនៅតាមហោជាង។ ប្រជាពលរដ្ឋនិងអ្នកទេសចរមានជំនឿថាពិតជាវិហារអាថ៌កំបាំង និងជាទីដ៏ស័ក្ដិសិទ្ធិផងដែរ។ វិហារឈើបុរាណនេះត្រូវបានចាត់បញ្ចូលជាបេតិកភណ្ឌជាតិ និងធ្វើការគ្រប់គ្រងដោយមន្ទីរវប្បធម៌និងវិចិត្រសិល្បៈខេត្តដែលក្រៅអំពីសំណង់បុរាណនេះ ក៏មានបន្សល់ទុកវត្ថុបុរាណជាច្រើន ដូចជាព្រះពុទ្ធរូបថ្មដែលមានអាយុកាល រាប់រយឆ្នាំ និងវត្ថុផ្សេងៗទៀត។ នៅមាត់ទន្លេនារដូវទឹកសម្រក មានឆ្នេរខ្សាច់ដែលអ្នកស្រុកនៅទីនេះនិយមមកលេងកម្សាន្ត។ ទឹកទន្លេថ្លាឈ្វេង រួមផ្សំនឹងទេសភាពដ៏ត្រកាលបានធ្វើឱ្យយើងមិនអាចបំភ្លេចបាន ប៉ុន្តែទីនេះប្រកបដោយហានិភ័យដោយមានអន្លង់ជ្រៅខ្លះ ដែលផ្លាស់ប្ដូរទីទៅតាមឆ្នាំ។",
    "descriptionEn": "The ancient Kandal Pagoda was built in the 18th century with an ancient wooden temple over 200 years old, a place that domestic and international tourists should not miss. This ancient wooden temple, which has been restored, is decorated with exquisite rosewood and tamarind carvings, especially the orchids in the hall. Residents and tourists believe that the temple is a mystery and a sacred place. This old wooden temple is classified as a National Heritage Site and is managed by the Provincial Directorate of Culture and Fine Arts. . At the mouth of the river during the low water season, there are sandy beaches that locals like to visit. The crystal clear river combined with the spectacular scenery made it unforgettable, but here it's dicey, with some deep canyons changing from year to year.",
