    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ភ្នំសំបុកមានកម្ពស់ប្រមាណ ៧០ម៉ែត្រ និងមានចម្ងាយប្រហែល៣០០ម៉ែត្រពីផ្លូវធំ។ ភ្នំមួយនេះគ្របដណ្ដប់ដោយដើមឈើច្រើនប្រភេទ ដែលមានដាក់ស្លាកឈ្មោះវិទ្យាសាស្ត្រ ហើយក៏មានជណ្ដើរនិងផ្លូវបេតុងឡើងទៅដល់វាលនៅជាន់ខាងលើ។ សំណង់លើកំពូលភ្នំនេះមានប្រាសាទតូចមួយ ផ្ទះ និងខ្ទម ដែលជាទីស្នាក់អាស្រ័យសម្រាប់ព្រះសង្ឃ អ្នកបួស និងដូនជី។ ផ្អែកតាមរឿងព្រេងនិទាន ភ្នំសំបុកសំបូរទៅដោយរ៉ែមាស ដែលជាងទងរបស់ស្ដេចបានទៅធ្វើគ្រឿងអលង្ការនៅទីនោះ។ ប្រជាជនធ្លាប់ហៅទីនេះថា \"សំបុកមាស\" ហើយក្រោយមកក៏ត្រូវបានហៅកាត់ត្រឹម \"ភ្នំសំបុក\"។",
    "descriptionEn": "Phnom Sambok is about 70 meters high and about 300 meters from the main road. This mountain is covered with many kinds of trees with scientific labels and also has stairs and a concrete path to the upstairs terrain. The building at the top of the hill has a small temple, a house and a hut, which is a residence for monks, nuns and nuns. According to legend, Phnom Sambok is rich in gold ore, which the king's mast went to make jewelry there. People called this place \"Golden Nest\" and later it was shortened to \"Phnom Sambok\".",
