    "id": "rac-k05020",
    "nameKh": "វត្តភ្នំព្រះ (ឆ្លូង), វត្តបព្វតវណ្ណារាម",
    "nameEn": "Phnom Preah Pagoda (Chhlong)",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ឆ្លូងភ្នំព្រះ គឺជាតំបន់វប្បធម៌ និងប្រវត្តិសាស្ត្រមួយនៅទីរួមស្រុកឆ្លូង។ មានអាស្រម និងព្រះពុទ្ធរូបដ៏ធំមួយ ដែលមនុស្សមកពីកន្លែងផ្សេងៗ បានទៅលេងកម្សាន្ត។ គេនិយាយថារូបសំណាកព្រះពុទ្ធនេះ ធ្វើពីឈើតាត្រាវ ដែលអណ្ដែតតាមទន្លេមេគង្គពីប្រទេសឡាវ ហើយមកជាប់នៅនឹងកំពង់ទឹកវត្តមួយ ដែលឥឡូវមានឈ្មោះថា វត្តសិលានទីឆ្លូង។ ឧបាសក និងឧបាសិកាក្នុងវត្តបាននាំគ្នាយករូបសំណាកនោះមករក្សាទុកក្នុងវត្តដើម្បីធ្វើជាគ្រឿងសក្ការៈបូជា។ ក្រោយមករូបសំណាកនេះបានពន្យល់សប្ដិអ្នកភូមិថា ការយករូបសំណាកនោះទៅដាក់នៅលើភ្នំខាងចុងភូមិនោះ នឹងផ្ដល់នូវសុខភាពល្អ និងភាពរុង រឿងដល់អ្នកភូមិ។ គេក៏បានធ្វើតាម ហើយតាំងពីពេលនោះមក គេក៏បានហៅភ្នំនោះថា “ភ្នំព្រះ” រហូតមក។ សព្វថ្ងៃនេះ វត្តភ្នំព្រះ គឺជាទីគោរពបូជាប្រកបដោយជំនឿមុតមាំនៃអ្នកស្រុកជិតឆ្ងាយ ហើយក៏មានសំណង់ថ្មីៗជាច្រើនផងដែរ។",
    "descriptionEn": "Phnom Preah is a cultural and historical site in the city of Chhlong district. There is a hermitage and a large Buddha statue that people visit from all over. It is said that the Buddha statue was made of cedar wood which floated down the Mekong River from Laos and landed next to a pagoda, now called Silanati Chhlong Pagoda. The monks and nuns of the pagoda took the statue and kept it in the pagoda as an object of worship. The statue later explained to the villagers in a dream that placing the statue on a hill at the end of the village would bring good health and prosperity to the villagers. They obeyed, and from then on they called this mountain \"Mountain of God\". Today, Phnom Preah Pagoda is a place of worship with the strong faith of people near and far, and there are also many new constructions.",
