    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "ក្នុងស្រុកព្រែកប្រសព្វ ខេត្តក្រចេះ ត្រើយខាងជើង ត្រង់ឃុំចំបក់ មានភ្នំមួយខ្ពស់ទទុងនៅក្បែរមាត់ទន្លេនោះ ឈ្មោះ \" ភ្នំសុពណ៌កាឡី \" ជាភ្នំស័ក្ដិសិទ្ធិ។ រឿងព្រេងតំណាលពីភ្នំនេះ មានដំណើរដូចរឿងព្រះវិហារសសរ១០០ដែរ ខុសត្រង់ក្រពើឈ្មោះ សុពណ៌កាឡី និងក្រពើឈ្មោះ \" នាងឱរ៉ៃ \" នៅទន្លេតូច ត្រង់កំពង់វត្តមហាលាភ ជាក្រពើរបស់លោកសង្ឃចិញ្ចឹម។ ភ្នំនេះពូកែស័ក្ដិសិទ្ធិណាស់ ព្រោះល្បីថា បើអ្នកណាទៅរៀនមន្តវិជ្ជានៅទីភ្នំនោះពេលកំពុងអង្គុយស្វាធ្យាយតែងមានពួកបិសាចមកល្បងធ្វើជាដុំមាសប៉ុនដូងទុំ ឬស្រីក្រមុំមកពិតអែបស្មាសងខាង បើអ្នករៀនវិជ្ជានោះ ភ្លាត់ចំណាប់ចង់បានរបស់ទាំងនោះ មុខជាត្រូវវាយបំបាក់កស្លាប់ពុំខាន។ សព្វថ្ងៃនេះ ទីតាំងមានបន្ថែមចំណុចពិសេសមួយទៀត គឺនៅជើងភ្នំប្រមាណ ២០០ម៉ែត្រ ខាងកើតខ្លោងទ្វារវត្តមានតម្កល់ព្រះបដិមាដែលមានបញ្ជុះសិលាចារឹកក្នុងនោះផង។",
    "descriptionEn": "In Prek Prosop district, Kratie province, on the north side of Chambok commune, there is a high mountain near the river, called \"Phnom Sopor Kali\", which is a holy mountain. Sopor Kali and the crocodile named \"Neang Orai\" on the small river at Kampong Pagoda Mohaleap are the crocodiles of the monks. The freaks come trying to make a nugget of gold like a ripe coconut or a virgin come true, pat each other on the shoulder. At the foot of the mountain, about 200 meters east of the pagoda gate, there is a statue with an inscription.",
