    "descriptionKh": "វិមានអនុស្សាវរីយ៍ ២ធ្នូ ត្រូវបានកសាងឡើង ដើម្បីរំលឹកអនុស្សាវរីយ៍នៃការបង្កើតឡើងនូវ រណសិរ្សសាមគ្គីសង្គ្រោះជាតិកម្ពុជា ដឹកនាំដោយ សម្ដេច ហេង សំរិន។ រណសិរ្សសាមគ្គីសង្គ្រោះជាតិកម្ពុជា ត្រូវបានបង្កើតឡើងនៅទីតាំងភូមិសាស្រ្តនៃវិមានអនុស្សាវរីយ៍នេះ កាលពីថ្ងៃទី២ ខែធ្នូ ឆ្នាំ១៩៧៨ ដែលជាថ្ងៃនាំទៅដល់ការផ្ដួលរំលំរបបខ្មែរក្រហមប្រល័យពូជសាសន៍ នៅថ្ងៃទី៧ ខែមករា ឆ្នាំ១៩៧៩។ ដូច្នេះហើយបានជានៅលើវិមាននេះ មានផ្ទាំងចម្លាក់ដែលបង្ហាញពីទិដ្ឋភាពទាហាន និងប្រជាជនក្នុងជំនាន់ខ្មែរក្រហម និងការទទួលជ័យជំនះលើការផ្ដួលរំលំរបបខ្មែរក្រហមដោយកងកម្លាំងរណសិរ្សសាមគ្គីសង្គ្រោះជាតិកម្ពុជា។",
    "descriptionEn": "The December 2 Memorial was erected to commemorate the founding of the Cambodian National Salvation United Front, led by Samdach Heng Samrin. The Kampuchean United Front for National Salvation was established at the geographical location of the monument on December 2, 1978, the day before the overthrow of the genocidal Khmer Rouge regime on January 7, 1979. That is why on this monument there are sculptures depicting soldiers and people during the Khmer Rouge era and the victory over the overthrow of the Khmer Rouge regime by the Kampuchean United Front for National Salvation.",
