    "nameKh": "វិហារសសរមួយរយ, វត្តព្រះវិហារសសរមួយរយ",
    "nameEn": "Hundred Pillars Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វិហារសសរ១០០ មានន័យថា «ប្រាសាទមានសសរ១០០» ដែលវត្តនេះត្រូវបានសាងសង់នៅសម័យព្រះបាទអង្គចន្ទរាជាទី២ ក្នុងសតវត្សទី១៦ ដើម្បីឧទ្ទិសដល់ព្រលឹងព្រះនាងវរភ័ក្ដ្រ ឬក្រពុំឈូក បុត្រីព្រះអង្គ។ ព្រះវិហារសសរ១០០ បែរមុខទៅ ទិសខាងជើង ខុសពីព្រះវិហារដទៃទៀត។ រឿងនិទានបានតំណាលថា ព្រះរាជាក្នុងពេលដែលព្រះរាជបុត្រីប្រឈួន បាននិមន្តព្រះចៅអធិការវត្តនាគសែន ស្រុកព្រែកប្រសព្វមកព្យាបាលជំងឺរបស់ព្រះរាជបុត្រី។ ពេលព្រះចៅអធិការមិននៅ នេនធន់ ជាសិស្សបានលួចរៀនវិជ្ជាមន្តអាគមប្រែក្រឡាខ្លួនទៅជាសត្វក្រពើតែមិនអាចប្រែក្រឡាមកជាមនុស្សវិញបាន។ ក្រោយមកក្រពើនេនធន់តែងតែដឹកគ្រូ ទៅព្យាបាលជំងឺបុត្រីរបស់ស្តេចជារឿយៗ រហូតថ្ងៃមួយមានក្រពើមួយទៀតឈ្មោះសុពណ៌កាឡី ចង់ផ្ចាញ់នេនធន់ ក៏បានបង្អាក់ដំណើរនេនធន់ នៅពេលកំពុងតែដឹកគ្រូមកពីវាំងវិញ។ ក្រពើទាំងពីរក៏បានប្រយុទ្ធគ្នានៅកណ្ដាលទន្លេ ហើយដោយមានការទើសទែង នេនធន់ក៏សម្រេចចិត្តលេបគ្រូចូលក្នុងពោះ។ ក្រោយប្រយុទ្ធគ្នាអស់រយៈពេល៣ថ្ងៃ៣យប់ទើបសុពណ៌កាឡីចាញ់ហើយក្លាយទៅជាភ្នំដែលមានឈ្មោះថា ភ្នំសុពណ៌កាឡី។ ពេលខ្ជាក់គ្រូចេញពីពោះវិញ លោកបានសុគតបាត់ទៅហើយ ទើបនេនធន់សោកស្តាយជាខ្លាំង ទើបចង់សម្លាប់បុត្រីរបស់ស្តេច ដោយគិតថានាងជាដើមហេតុធ្វើឱ្យគ្រូរបស់ខ្លួនស្លាប់។ នេនធន់បានលេបយកបុត្រីរបស់ស្តេចក្នុងពេលដែលនាងចុះលេងនៅកំពង់ទឹក ទើបព្រះចន្ទរាជាបញ្ជាឱ្យគេទៅតាមចាប់បាននេនធន់នៅសំបូរ ហើយវះពោះក្រពើនោះយកបុត្រីមកបញ្ចុះ ដោយបានសាងសង់វត្តសសរ ១០០ ផងដែរ។ នៅពីមុខវិហារសសរ១០០ ស្តេចបានសង់ចេតិយមួយធំ ហើយដើរចាប់ស្ត្រីមានផ្ទៃពោះ២០នាក់មកសម្លាប់យកក្បាលមកធ្វើជាគ្រឹះ និងសាងរូបក្សត្រីក្រពុំឈូកលើចេតិយនោះផង។ ស្បែកក្រពើនេនធន់ត្រូវបានពន្លះ យកទៅឆ្កាងនៅក្បែរចេតិយនោះ ដែលក្រោយមកក្លាយជាទំនៀមចងទង់ក្រពើក្នុងបុណ្យសពផងដែរ។ កាលពីជំនាន់ដើមគ្មានអ្នកណាម្នាក់ហ៊ានដើរកាត់មុខចេតិយនោះទេ ជាពិសេសស្ត្រីមានផ្ទៃពោះ។ រយៈក្រោយមកព្រះវិហារត្រូវរន្ទះបាញ់ឆេះសសរ ២២ ដើម ទើបគេបានស្ថាបនាព្រះវិហារនេះឡើងវិញ ប៉ុន្តែមានសសរតែ ៧៨ដើមទេ។ នៅឆ្នាំ១៩៧៨ ព្រះវិហារត្រូវបានរុះរើសាងសង់ឡើងវិញ ដោយមានសសរ១១៦ដើម។",
    "descriptionEn": "Vihear Sarsor 100 means \"100 Pillars Temple\", which was built during the reign of King Ang Chan Reacha II in the 16th century to dedicate the soul of Princess Vorapheak or Krapum Chhouk, his daughter. The 100-pillared church faces north, unlike other churches. Legend has it that the king, while his daughter was in a coma, summoned the chief abbot of Pagoda Neak Sen, Prek Prosop district to treat her. When Chief Inspector Nen Thorn was not a student, he stole magic to turn his cell into a crocodile, but was unable to turn his cell into a human. Later, the crocodile Nen Thorn used to take the professor to treat the king's daughter, often until one day another crocodile named Sopor Kali, who wanted to defeat Nen Thorn, interrupted Nen Thorn by bringing the professor back from the palace. . The two crocodiles also fought in the middle of the river, and Nen Thorn decided to swallow the professor in his stomach. After fighting for 3 days and 3 nights, Sopor Kali lost and became a mountain called Phnom Sopor Kali. When he threw the teacher out of his stomach, he was already dead, so Nen Thorn was very sad and wanted to kill the king's daughter, thinking that she was the cause of his teacher's death. Nen Thorn swallowed the king's daughter while visiting the port, so Preah Chan Reacha ordered them to go and capture Nen Thorn in Sambo and dissect the crocodile's abdomen, bury his daughter and build a pagoda to 100 pillars. In front of the 100-pillar temple, the king built a large stupa and captured 20 pregnant women, killed them, used their heads as a foundation, and built a pagoda without a shower on the stupa. The durable crocodile skin was stripped and crucified near the stupa, which later became a custom to tie crocodile flags at funerals. In the past, no one dared to walk in front of the stupa, especially pregnant women. Later, the temple was struck by lightning and 22 pillars were rebuilt, but there were only 78 pillars. In 1978 the church was demolished and rebuilt with 116 pillars.",
