    "descriptionKh": "ប្រាសាទតែមួយគត់ក្នុងខេត្តដែលអាចទៅដល់ដោយស្រួល បន្សល់រូបរាងតែជាគំនរឥដ្ឋបែកបាក់និងសំណល់ជញ្ជាំងតិចតួចគួរឱ្យសោកស្ដាយពន់ពេក។ ក្រៅពីនេះក្នុងខេត្តមានប្រាសាទដទៃទៀតដែលនៅកប់ក្នុងទីឆ្ងាយមិនទាន់មានផ្លូវធ្វើដំណើរទេសចរណ៍ទៅដល់ដោយស្រួលបានដូចជាប្រាសាទល្បើកស្រុត ប្រាសាទព្រះធាតុខ្វាន់ពីរជាដើម។ លោកយាយដែលជាអ្នកនៅថែរក្សាអាស្រមមួយក្នុងទីប្រាសាទបានឱ្យដឹងថា ពីមុនប្រាសាទនេះនៅមានរូបរាងល្អប្រកបដោយប្រាង្គចំនួនប្រាំ បែរទៅកើតសង់រត់ជួរគ្នាបីខាងមុខនិងពីរខាងក្រោយ ប៉ុន្តែត្រូវបានគាស់បំផ្លាញដោយជនខិលខូចរកកំណប់។ គាត់បន្ថែមទៀតថា ជាអកុសលពួកជនអស់ទាំងនោះបានស្លាប់អន្តរធានអស់ទៅហើយ(?)។ នៅទីនោះ គេអាចឃើញសំណល់វត្ថុបុរាណ ដូចជាផ្ដែរធ្វើពីថ្មភក់ និងគ្រឿងបង្គុំសំណង់ផ្សេងៗទៀត។",
    "descriptionEn": "The only easily accessible temple in the province, unfortunately leaving only a pile of broken bricks and some remnants of walls. Also in the province there are other temples which are buried in the distance, there is no easy way for tourists to get to them, such as Prasat Lbeuk Srot, Prasat Preah Theat Kvan Pi and and so on. The grandmother, who is in charge of a hermitage in the temple, said that before the temple was still in good condition with five towers, turned to build three rows in front and two behind, but was demolished by the wicked in search of treasure. He added that, unfortunately, all these people are already deceased (?). You can see artifacts such as sandstone slabs and other building materials there.",
