    "nameEn": "Lbeuk Srot Temple Foundation",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទឯកោកណ្ដាលព្រៃចម្ងាយប្រមាណជាងមួយគីឡូម៉ែត្រពីផ្លូវភូមិ។ តាមឯកសាររបស់ CISARK ប្រាសាទនេះមាន៖ ប្រាង្គបីធ្វើពីឥដ្ឋបែរមុខទៅកើតនិងប្រាង្គមួយទៀតធ្វើពីឥដ្ឋបែរមុខទៅជើង។ ខ្លោងទ្វារកំពែងធ្វើពីឥដ្ឋនៅខាងកើតនិងប្រាង្គមួយទៀតធ្វើពីឥដ្ឋបែរទៅខាងលិច។ ប្រាសាទនេះមានលក្ខណៈពិបាកពិពណ៌នាពីរូបរាងដោយឯកសាររបស់លោក H. Parmentier រៀបរាប់ថាប្រាសាទនេះមានប្រាង្គពីរខូចខាតអស់រត់ដូរកើត-លិចបែរមុខទៅជើង។ មេទ្វារ ខាងលិចនៃប្រាង្គខាងកើតមានសិលាចារឹកបីបន្ទាត់ K 135 ចំណែកមេទ្វារខាងកើតនៃប្រាង្គ ខាងលិចមានសិលាចារឹក២៩បន្ទាត់ K 138។ ប្រាសាទបានរងការខូចខាតដោយស្នាដៃធម្មជាតិ និងស្នាដៃមនុស្ស ដែលជីករូងកកាយរកកំណប់ដែលគេជឿថាមាននៅក្រោមឫសសីមានៃប្រាសាទ។ សព្វថ្ងៃនេះ គេអាចឃើញតែសំណល់ឥដ្ឋបុរាណនៅរាយប៉ាយ និងខឿនព្រមទាំងអាចម៍ដីដែលពូនគរដោយការជីកកកាយ។",
    "descriptionEn": "Solitary temple in the middle of the forest, more than a kilometer from the village road. According to CISARK documents, the temple has: three east-facing brick towers and one brick tower. The gate is brick to the east, and the other tower is brick facing west. The temple is difficult to describe in appearance, with documents from H. Parmentier describing the castle as having two completely damaged towers, back and forth, facing east. The west gate of the east tower bears three K 135 inscriptions, while the east gate of the west tower bears 29 K 138 line inscriptions. The temple has been damaged by natural and man-made excavations, which are believed to be below the temple boundaries. Today, only the remains of ancient bricks can be seen scattered and mounded, along with rubble piled up from the excavations.",
