    "id": "rac-k05027",
    "nameKh": "វត្តថ្មគ្រែ, វត្តមញ្ចសិលា",
    "nameEn": "Thmor Kre Pagoda",
    "categorySlug": "cultural",
    "categoryKh": "រមណីយដ្ឋានវប្បធម៌ / ប្រវត្តិសាស្ត្រ",
    "categoryEn": "Cultural & Historical Site",
    "descriptionKh": "វត្តមញ្ចសិលា ថ្មគ្រែ មានឈ្មោះជាភាសាបាលី និងភាសាខ្មែរជាការបកប្រែផ្ទាល់។ ជាភាសាបាលី មញ្ច = គ្រែ ឯ ពាក្យ សិលា គឺ ថ្ម។ វត្តចំណាស់មួយនេះ មានភាពល្បីល្បាញ ដោយនៅច្រាំងទន្លេមុខវត្ត មានដុំថ្មមួយ ដែលជាសិលាចារឹក លេខ K.122។ ក្រៅពីនេះ ក្នុងទីវត្តមានសំណល់ បល្ល័ង្កនិងបំណែកផ្ដែរ ព្រមទាំងជាទីតាំង ដែលជាប្រភពសិលាចារឹកពីរទៀត គឺ K.926, K.131។ ភ្ញៀវទេសចរអាចចាំមិនភ្លេចនូវក្រឡានដែលមានរសជាតិឆ្ងាញ់នៃអ្នកស្រុកថ្មគ្រែ ដែលពិសេសដាច់គេ។ អ្នកភូមិថ្មគ្រែភាគច្រើនមានរបរធ្វើនំក្រឡាន ហើយចង់ទទួលបានសិទ្ធិប្រើប្រាស់ម៉ាកសម្គាល់ភូមិសាស្ត្រផ្ដាច់មុខដូចផ្លែក្រូចថ្លុងកោះទ្រង់ដែរ។",
    "descriptionEn": "Manh Seila Thmor Kre Pagoda is named in Pali and Khmer as a direct translation. In Pali manh = bed, the word stone is stone. This ancient pagoda is famous for having a stone pagoda on the river bank in front of the inscription number K.122. Moreover, in the presence of the remains of the throne and the fragments, as well as the location of the source of the other two inscriptions, K.926, K.131. Visitors cannot forget the delicious car of the inhabitants of Thmor Kre, which is very special. Most of Thmar Kre villagers make 'Kralan' cakes and want to get the right to use exclusive geographical brands like Koh Trong grapefruit.",
