    "id": "rac-k05028",
    "nameKh": "គ្រឹះប្រាសាទទួលកំណប់ត្រពាំងព្រៃ",
    "nameEn": "Tuol Kamnob Trapeang Prey Temple Foundation",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ទួលកំណប់ត្រពាំងព្រៃ ជាទីតាំងដែលធ្លាប់រកឃើញនៅដើមសតវត្សទី២០នូវសិលាចារឹកមួយក្នុងប្រាសាទបុរាណបាក់បែកសម័យសតវត្សរ៍ទីប្រាំពីរ លេខ K-127 ដោយ អាដេម៉ាឡឺគ្លែ នៅក្នុងឆ្នាំ១៨៩១។ សិលាចារឹកនេះមានភាពល្បីល្បាញ ថាជាសិលាចារឹកចាស់ជាងគេ ដែលមានលេខសូន្យ តាមរយៈកាលបរិច្ឆេទ ឆ្នាំ៦០៥ នៃមហាសករាជ ត្រូវនិងឆ្នាំ ៦៨៣ នៃគ.ស។ សម័យកាលនេះគឺស្ថិតនៅចុងរជ្ជកាលរបស់ព្រះមហាក្សត្រិយានីខ្មែរព្រះនាមជយទេវី (៦៨១-៧១៣) ជាព្រះមហាក្សត្រខ្មែរមួយព្រះអង្គដែលបានគ្រងរាជសម្បត្តិនៅចុងសម័យចេនឡា។ យើងមិនអាចដឹងបានច្បាស់លាស់អំពីពត៌មានស្តីពីព្រះរាជិនីអង្គនេះឲ្យប្រាកដបានច្រើននៅឡើយទេ ប៉ុន្តែនៅលើខ្នងទំនប់បារាយណ៍គេបានរកឃើញសិលាចារឹកមួយផ្ទាំងដែលស្តីពីព្រះរាជកិច្ចរបស់ក្សត្រិយានីអង្គនេះទាក់ទងទៅនិងវិស័យសាសនាព្រមទាំងពាក្យតំអូញតំអែររបស់ព្រះនាង ស្តីពីរាជកិច្ចផងដែរ។ សិលាចារឹកប្រើអក្សរខ្មែរបុរាណ ចន្លោះស.វទី ៦ ដល់ ៨ នៅលើបន្ទះមេទ្វារប្រាសាទ មាន ១៣ បន្ទាត់ ស្ដីពី តង្វាយរបស់ម្រតាញវិទ្យាកីត្តិ ថ្វាយដល់ព្រះស្រីអមរេស្វរ កាលពីឆ្នាំ៦០៥ ...។ នៅខាងជើងទួលនេះក៏មាន ទួលប្រាសាទបែកបាក់ជាច្រើនទៀត ដូចជា ទួលកំណប់ត្រពាំងថ្មជាដើម។",
    "descriptionEn": "Toul Kompong Trapeang Prey is the site where an inscription was found in the early 20th century on the ruins of the 7th century ruins, K-127, by Adema le Claire in 1891. This inscription is known as the oldest inscription with the number zero up to the date 605 AD and 683 AD. This period is at the end of the reign of Khmer Queen Joy Devi (681-713), a Khmer king who reigned during the late Chenla period. We cannot know with certainty the information regarding this queen, but on the back of the Baray, an inscription was found on the queen's handiwork related to religion and sayings, as well as her sayings on royal affairs. Inscriptions using the ancient Khmer script between the 6th and 8th centuries on the main gate of the temple have 13 lines about the martial arts offerings to the goddess Ameresvar in 605.... North of this hill there are many other ruined temples, such as Tuol Kompong, Trapeang Thmor, etc.",
    "photoUrl": "https://raw.githubusercontent.com/igpubinfo-max/Khmer-Food-Tourism/8d322f9/public/destinations/rac-k05028.jpg",
