    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទគុកខាងជើងមានស្ថាបត្យកម្មដូចប្រាសាទអាស្រមមហាឥសីនៅសម្បូរព្រៃគុក។ កូនប្រាសាទនេះមានរាងជាបន្ទប់តូចមួយធ្វើអំពីថ្មភក់ សម្រាប់តាបសឥសីសមាធិ។ ប្រាសាទបែរមុខទៅទិសខាងកើតសំដៅទន្លេមេគង្គ មានរាងតូចច្រឡឹងទំហំប្រមាណ ២ ម៉ែត្របួនជ្រុង គួរឱ្យគយគន់មិនឆ្អែតភ្នែកឡើយ។ ខ្លោងទ្វារខាងកើតមានលម្អដោយសសរពេជ្រមួយគូរាងមូល ទ្រក្បាច់ផ្ដែរមានចម្លាក់ព្រះវិស្ណុផ្ទុំលើនាគអនន្តនៅចំកណ្ដាលអមដោយមេដាយក្បាច់ផ្កាឈូកទាំងសងខាង។ គួរកត់សម្គាល់ថាប្រាសាទសង់ឡើងដោយសន្លឹកថ្មភក់ចំនួន១១សន្លឹក។",
    "descriptionEn": "North Kuk Temple has similar architecture to Asrom Moha Eisei in Sombo Prei Kuk. The temple is shaped like a small room made of sandstone for hermits to meditate. The temple is in small shape of about two square meters faces east towards the Mekong River. The east entrance is decorated with a pair of round colonettes which support the lintels with sculpture of Shiva sleeping on Anada dragon surrounding by lotus on both sides. Noticeably, the temple was built by only 11 slabs of sandstone.",
