    "id": "rac-k06003",
    "nameKh": "ប្រាសាទគុកខាងត្បូង",
    "nameEn": "South Kuk Temple",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទមួយសង់អំពីឥដ្ឋមានកំពស់ប្រមាណជា ១៥ ម៉ែត្រ ក្នុងចំណោមប្រាសាទ សម័យបុរេអង្គរដ៏ល្អស្អាតស្ថិតក្នុងរចនាបថសម្បូរព្រៃគុក។ ប្រាសាទគុកខាងត្បូងបែរមុខទៅទិសខាងកើត សង់ឡើងសម័យបុរេអង្គ ក្នុងរចនាបថព្រៃក្មេង មានប្លង់បាតរាងការ៉េដោយជ្រុងនីមួយៗមានប្រវែង ៦.៥ម.។ វិមានអណ្ដែតនេះមានទ្វារបីទៀតជាទ្វារបញ្ជោត ហើយក្លោងទ្វារខាងកើតនៅសល់តែមេទ្វារទេ រីឯផ្ដែរសសរពេជ្រ ត្រូវបានជនទុច្ចរិតលួចបាត់ទៅហើយ។ លើមេទ្វារទាំងពីរ មានចារិកចុះលេខ K81 ជាភាសាសំស្ក្រឹត ដែលរៀបរាប់ពីព្រិត្តិការណ៍ ក្នុងរដ្ឋកាលរបស់ព្រះបាទភវវរ្ម័ន ក្នុងអំឡុងស.វទី ៦ និងទី ៧ នៃគ.ស។ ខាងក្នុងប្រាសាទមានបំណែកសិលាចារឹកមួយទៀតចារឹកនៅស.វ.ទី៧ផងដែរ ឯនៅផ្នែកខាងមុខមានសិលាចារឹកសហសម័យមួយចុះកាលបរិច្ឆេទជាពុទ្ធសករាជ២៤៥០ មានអាយុកាល១១៤ឆ្នាំមកហើយ។",
    "descriptionEn": "A brick temple, about 15 meters high, is one of the most beautiful pre-Angkorian temples in the Sambor Prei Kuk style. The Soth Kuk Temple is built in the pre-Angkorian period in the style of Prey Kmeng, with a square base which each corner is 6.5 m long. This floating temple has three blind doors, and the east gate remains only the door frame; unfortunately, and the colonnettes have been stolen by the wicked. On both of the door frames, there is an inscription K.81 in Sanskrit which told the events in the king Bhavavarman in the 6th and 7th century. In the temple, there another piece of inscription in the 7th century. In the front of the temple, there is a contemporary inscription in dated in 2450 B.E, which lasted about 114 years.",
