    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទទោលតូចមួយនៅកណ្ដាលវាលស្រែមិនមានព្រៃជុំវិញ ដោយទីនេះជាផ្លូវចូលទៅកាន់វត្តស្រងែ។ ប្រាសាទធ្វើពីថ្មបាយក្រៀមសុទ្ធ ទំហំ ៣ x ៣ ម. កម្ពស់ ៣.៥ ម. មិនមានទ្វារឬចម្លាក់អ្វីទេ តែនៅរក្សារូបរាងបានល្អណាស់ គ្រាន់តែរង្គោះផ្នែកដំបូលបន្តិច ទើបគេចងរឹតដោយខ្សែកាប។ ទំហំប្រាសាទដ៏តូចនេះ សក្ដិសមនឹងការដាក់តម្កល់រូបអ្នកតារបស់អ្នកស្រុកនៅទីនោះណាស់។ ប្រាសាទនេះមានទម្រង់ប្រហាក់ប្រហែលគ្នាទៅនិងសំណង់តូចមួយក្នុងប្រាសាទប្រែរូប ដែលតាមលក្ខណៈសំណង់គួរតែជាទីបូជាសពឬក៏ជាចេតិយមួយតែប៉ុណ្ណោះ។",
    "descriptionEn": "A single temple in the middle of rice field with no bushes around, it is also the way to go to Sro Gne pagoda. The temple was built of laterite in the size of 3m. x 3m. and 3.5 m. height, no blind doors or any sculptures around. The temple is still in good condition, except the small part of the roof has been collapsed, and it has been tied up with a cable. This small temple is suitable for keeping Neak Ta statue by villagers there. The structure of this temple is similar to a small construction in Pre Rup temple which is assumed as a crematorium or just a stupa.",
