    "descriptionKh": "ប្រាសាទដែលស្ថិតនៅលើកូនភ្នំគុកកម្ពស់ប្រហែលជា ២០ម. ប៉ុន្តែស្ថិតក្នុងបរិវេណបន្ទាយកងយោធា។ ប្រាសាទឥដ្ឋរាង៤ជ្រុង សង់បែរមុខទៅខាងកើត ស៊ុំទ្វារ និងផ្ដែរធ្វើពីថ្មភក់។ បំណែកផ្ដែរដែលធ្លាក់បាក់ជាពីរកំណាត់ មានចម្លាក់រូបព្រះឥន្ទ្រគង់លើដំរីឰរាវ័ណសឲ្យឃើញថាប្រាសាទនេះត្រូវបានសាងសង់នៅស.វទី១០-១១ នៃគ.ស ហើយមានស្ថិតក្នុងរចនាបថបាពួន ដែលអាចបញ្ជាក់ពីអាយុកាលនៃប្រាសាទ។ យើងអាចគ្រាន់តែទស្សនាពីចម្ងាយនូវទីតាំងនេះ។",
    "descriptionEn": "This temple is located on the 20-meter-high mountain called Phnom Kuk, and it is in the compound of military barracks. The quadrangular brick temple faces east, with a door frame and lintels made of sandstone. The fragments, which fall into two parts, have a statue of Indra sitting on a white elephant, indicating that the temple was built in the 10th-11th centuries AD in Baphuon style, which can be traced back the age of the temple. We can only see the temple from a distance.",
