    "id": "rac-k06006",
    "nameKh": "ប្រាសាទគុកព្រីងជ្រុំ",
    "nameEn": "Kuk Pring Chum Temple",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទធ្វើពីឥដ្ឋមួយដែលបែកបាក់អស់មួយផ្នែកធំ នៅតែសំណល់ជញ្ជាំង ចំណែកដំបូលខូចអស់គ្មានសល់ ហើយប្រកបដោយទ្វារបញ្ឆោត៣ទៀតតាមទិសធំនីមួយៗ ។ ប្រាសាទមានរាងការ៉េ ទំហំ ៣.៥ x ៣.៥ម. នៅសល់មេទ្វារសងខាងដែលមានសិលាចារឹក ចុះលេខ K92 ។ ប្រាសាទនៅកណ្ដាលវាលស្រែនេះ មានកំពែងថ្មបាយក្រៀមព័ទ្ធជុំវិញប្រវែង២៥ម.x២០ម. ខ្លោងទ្វារកំពែងធ្វើអំពីថ្មបាយក្រៀម មានច្រកចូលតែមួយមានកសិន្ធុព័ទ្ធជុំវិញ និងមានត្រពាំងមួយ។ ប្រាសាទសង់ឡើងក្នុងកំឡុងស.វ.ទី១១ ហើយមានខ្ទមអ្នកតាមួយសង់នៅទីនោះ ដែលប្រហែលជាសង់ដោយអ្នកភូមិឬអ្នកលាបំណន់ណាម្នាក់។ ទោះប្រាសាទស្ថិតនៅមិនឆ្ងាយពីវត្ត ក៏មិនមានការថែរក្សា ហើយត្រូវបានបំផ្លាញដោយធម្មជាតិ និងមនុស្ស។ ដោយឡែកសិលាចារឹកលេខ K92 នៅលើមេទ្វារចារឹករាក់ៗហើយក៏ទទួលរងការរលុបសឹករឹចរិលផងដែរ ចារក្នុងឆ្នាំ ១០២៨ គិតជាគស. នាសម័យអង្គររៀបរាប់ពាក្យគោរពបូជាដល់អង្គព្រះសិវ ព្រះទេវី ព្រះវិស្ណុ និងព្រះព្រហ្ម ព្រមទាំងការសរសើដល់ព្រះកិត្តិគុណរបស់ព្រះបាទសូរ្យវរ្ម័នទី១ផងដែរ។",
    "descriptionEn": "It is a brick temple, partly broken, only wall ruins remain. The roof and three false doors in each direction were completely destroyed. The temple is in square shape with 3.5 m. X 3.5 m. size. The both door jambs with inscription K92 remains. The temple in the middle of the paddy field has a laterite wall around 25m x 20m. The laterite gate has a single entrance, surrounded by a casket and a pond. The temple was built in 11th century with a small shrine nearby, probably built by villagers or any prayers. The temple is in bad condition due to nature and human. This temple is lack of caring and preservation even it is closed to the pagoda. In particular, the inscription number K92 on the door jambs was shallow carved in 1028 in Angkorian period and it was suffered by the erosion. This inscription describes the words of worships to the lord Shiva, Devi, Vishnu, and Brahma, as well as praise for the honor of King Suryavarman I.",
