    "descriptionKh": "ប្រាសាទគុកព្រះធាតុ ត្រូវបានសាងសង់ឡើង នៅក្បែរដងទន្លេមេគង្គ នៅលើចង្កេះភ្នំហាន់ជ័យ។ ដោយសារបូជនីយដ្ឋាន ដ៏សំខាន់នេះមាន លក្ខណៈស្រដៀង នឹងប្រាសាទអាស្រមមហាឥសី នៅស្រុកអង្គរបុរីទើបបានជាគេបញ្ចូលប្រាសាទនេះ ក្នុងសម័យកាលនគរភ្នំមានរចនាបថភ្នំដា។ ប្រាសាទសង់ឡើងដោយថ្មបាសាល់ មានរាងការ៉េជ្រុងទំហំ ៤.៥ ម. និងកម្ពស់ ៥ ម៉ែត្រ។ ប្រាសាទត្រូវបានជួសជុលក្រោមជំនួយថវិការពីសហរដ្ឋអាមេរិក។ ប្រាសាទដ៏ល្អវិចិត្រមានតែពីរក្នុងប្រទេសកម្ពុជានេះសង់ឡើងក្នុងសម័យអន្តរកាលរវាងនគរភ្នំ និងចេនឡា ពោលគឺស.វ ទី ៦ នៃគ.ស ក្នុងរាជព្រះបាទធរណិន្ទ្រវរ្ម័នទី១។ គេបានជីករក ឃើញរូបចម្លាក់គោនន្ទិនជាយានជំនិះរបស់ព្រះឥសូរមួយអមទ្វារប្រាសាទ ហើយយកទៅតម្កល់នៅមន្ទីរវប្បធម៌ខេត្តកំពង់ចាម។ តាមការដំណាលរបស់អ្នកភូមិ ពីដើមឡើយមានតម្កល់នូវចម្លាក់របស់ព្រះអាទិទេពស្រីមួយព្រះអង្គ ធ្វើអំពី ថ្លើមថ្មខ្មៅ ដែលគេឲ្យឈ្មោះថានាងខ្មៅ (ការពិតគីតំណាងឲ្យព្រះនាងឱមា) តែត្រូវពួកចោរលួចយក ទៅលក់បាត់ មុនឆ្នាំ ១៩៦០។ ខាងក្នុងគ្មានការ តុបតែងអ្វីឡើយ ក្រៅពីរូបចម្លាក់តំណាង ព្រះនាងឱមា ឬនាងខ្មៅ នឹងសោមសូត្រសម្រាប់បង្ហូរទឹកមន្ត។ ទ្រង់ទ្រាយដំបូលរាងកោងជាថ្នាក់ៗតួប្រាសាទត្រូវបាន សាងសង់លើ ខឿនមួយ ដ៏រឹងមាំ ដែលមាន ៣ ថ្នាក់ ដោយថ្នាក់នីមួយៗ មានរចនាជាក្បាច់អង្កែ ព័ន្ធជុំវិញទម្រង់មុខមនុស្ស មានពាក់ក្រវិលធំៗ ហៅថា ឃូឌូ។",
    "descriptionEn": "Kuk Preah Theat Temple was built next to Mekong River, on the hillside of Hanchey Mountain. Since this temple is very significant and similar to Asrom Moha Eisei Temple in Angkor Borei district, it has been included in the Nokor Phnom era, with Phnom Da style. The temple was built from Basal stones in a square shape of 4.5 m. in size, and 5 m. high. This temple was repaired with US funding. This magnificent temple is believed to be built during the transitional period of Nokor Phnom and Chenla, around the 6th century during the reign of King Thoranindravarman 1. They dug up a statue of Nandi, a sacred cow of the lord Shiva, at the entrance of the temple and took it to the Kampong Cham Provincial Department of Culture. According to the villagers, there is a statue of a female goddess made of black jade, which is called Neang Khmao (actually, it represents Princess Oma), but was stolen and sold in 1960. Inside, there are no decorations other than statues representing Princess Oma or Neang Khmao and chanting for mantras, sacred water. Layered curved roof of the temple is built on a solid ridge with three tiers, each of which is designed in a circular pattern around the face of a person wearing large earrings called Kudu.",
