    "nameKh": "ប្រាសាទគុកយាយហម",
    "nameEn": "Kuk Yeam Ham Temple",
    "categorySlug": "temple",
    "categoryKh": "ប្រាសាទបុរាណ / បេតិកភណ្ឌ",
    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទគុកយាយហម ត្រូវបានបាក់បែកអស់ច្រើន ដូចជាដំបូលបានបាក់ធ្លាក់ចូលក្នុងតួប្រាសាទ ខឿនរង្គុះរង្គើ។ ប្រាសាទនេះត្រូវបានកសាងដោយព្រះបាទជ័យវរ្ម័នទី ៧ ក្នុងសតវត្សរ៍ទី១៣ មានរាងជាកាកបាទ ហើយមានទ្វារទៅកាន់ទិសទាំងបួន។ ប្រាសាទមានទំហំ១១ x ១១ ម. មានយ៉តាមទ្វារនីមួយៗ សង់នៅលើខឿនថ្មបាយក្រឿមកម្ពស់ ២ម. ដែលជាខឿនរាងការ៉េ ទំហំជ្រុង ១៦ម.។ ប្រាសាទនេះសង់ពីថ្មភក់ ក្នុងរចនាបថបាយ័ន ដើម្បីឧទ្ទិសដល់ពុទ្ធសាសនាមហាយាន តែយើងសង្កេតឃើញសំណល់ប្រាសាទបុរាណពីឥដ្ឋសតវត្សទី៧ ឬ ៨ នៅលើទួលជាប់នឹងតួប្រាសាទនេះដែរ ដែលប្រាង្គ ២ ទៀតធ្វើពីឥដ្ឋនោះបានរលំបាក់បែកតាំងពីដើម ស.វ. ទី ២០។ កំពែងមានពីរជាន់ ទី១ធ្វើពីថ្មបាយក្រៀមមានកសិន្ធុព័ទ្ធពីខាងក្រៅ។ កំពែងទី ២ ធ្វើពីដីហើយមានកសិន្ធុព័ទ្ធពីខាងក្រៅដែរ។ ស្រះទឹកបុរាណ ២ អមសងខាងផ្លូវចូល និងស្រះទឹកបុរាណមួយទៀត ស្ថិតនៅខាងត្បូង ចំណែកទន្លេអុំស្ថិតនៅខាងកើតឆៀងខាងជើងបន្តិច។ ទីនេះមាន រូបចម្លាក់ជាច្រើនធ្វើពីថ្មភក់, សសរស្ដម្ភ ៨ ជ្រុង, ផ្ដែរជាផ្ទាំង, បល្ល័ង្កជាច្រើន, និងសិលាចារឹក K. 86 ត្រូវបានគេយកទៅទុកនៅ វត្តសង្កែ ដែលស្ថិតនៅក្បែរនោះ។ នៅឆ្នាំ ២០០៤ ទីនេះ គេរកឃើញសិលាចារឹកមួយចំនួនទៀត ដែលភាគច្រើនចារជារូបសញ្ញា។ មានមតិមួយចំនួនសង្ស័យថាទីតាំងនេះជាភូមិកំណើតនៃព្រះនាងជ័យរាជទេវី និងព្រះនាងឥន្ទ្រទេវី អគ្គមហេសីនៃ ព្រះបាទជ័យវរ្ម័ន ទី ៧។",
    "descriptionEn": "Kuk Yeay Horm temple was destroyed a lot. The roof collapsed, and the platform was shaken. This temple was built by King Jayavarman 7 in 13th century in a Red Cross-shape with four doors to the four directions. The temple is 11 x 11 m. size. There is a balcony with each door built on a 2m. high-laterite square-platform which each platform is a square block of 16 m. The temple is built of sandstone in the Bayon style to dedicate to Mahayana Buddhism, but the remains of the ancient temple made of brick from the 7th or 8th century on the hill next to the temple; the other two towers also made of brick collapsed in the early 20th century. There are two layers of walls which the first layer was made of laterite surrounded by moats, and the second layer was made of soil with a moat surrounded. There are two ponds along the entrance; another ancient pond is in the south, and Tonle Om is in the South-East. Here, there are many sandstone sculptures, eight-corner pillars, lintels, thrones, and K.86 inscription which was kept in Sang Ke pagoda. In 2004, another piece of inscription was found which inscribed in pictures and symbols. It was wondered if this site is the hometown of the Princess Jay Rachdevi and Indra Devi, the wife of Jayavarman 7.",
