    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទនេះបែរមុខទៅទិសខាងកើតត្រង់ទៅរកទន្លេមេគង្គ សង់អំពីឥដ្ឋ មេទ្វារធ្វើអំពីថ្មថ្លើមអណ្ដើក ផ្នែកខាងមុខមានសេសសល់យ៉សាងអំពីថ្មបាយក្រៀម។ ប្រាសាទនេះសាងសង់នៅស.វ.ទី៧ និងមានការជួសជុលបន្ថែមនៅសម័យអង្គរ។ ប្រាសាទមានផ្ទៃបាតរាងការ៉េ ទំហំ ៦ x ៦ម. ប្រមាណ ៩ម. គិតទាំងផ្នែកកប់ក្នុងដី។ ប្រាសាទត្រូវបានជួសជុលនាសម័យអង្គរហើយមានគ្រឿងសំណង់ខ្លះយកពីប្រាសាទចាស់។ នៅលើមេទ្វារខាងត្បូងច្រកចូលធ្លាប់មានសិលាចារឹកសតវត្សទី៧ ចុះលេខ K1042 នៅលើធ្នឹមទ្វារមានសេសសល់អក្សរចារឹកដែលចែកជា២ផ្នែកមានភាសាសំស្ក្រឹត និងភាសាខ្មែរ ផ្នែកភាសាខ្មែររៀបរាប់ពីព្រះនៅឯដងព្រះទឹក ដែលទំនងជាដងព្រែកមួយដែលនៅជាប់និងប្រាសាទសព្វថ្ងៃនេះត្រូវលុបបាត់។",
    "descriptionEn": "The temple faces east, straight towards the Mekong River, built of brick, the door frame is made of black jade, the front has a balcony built of laterite. This temple was built in the 7th century AD and was renovated during the Angkorian period. The temple has a square bottom surface, size 6 x 6 m., bout 9 m. including the buried section. The temple was repaired in the Angkorian period, and some construction parts were taken from the old temple. On the south door frame of the entrance, there is a 7th century inscription K1042. On the beam, there are remains of inscription which are available in Sanskrit and Khmer language. The inscription in Khmer language describes the god at the river, Dang Preah Tek, which is likely to be a canal next to the temple today and has been filled with land.",
