    "categoryEn": "Historical Temple / Heritage",
    "descriptionKh": "ប្រាសាទគុកអំពិលទ្វារមានកំពែងថ្មបាយក្រៀមកំពស់ប្រមាណ ២.៥ ម. ព័ទ្ធជុំវិញ ទំហំ ៣០ x ៣០ ម.។ តាមកំណត់ត្រាចាស់ទីនេះជាក្រុមប្រាសាទមានប្រាង្គបីសង់លើខឿនតែមួយ បែរមុខទៅកើត រត់ជួរជើង-ត្បូង តែគួរឱ្យស្ដាយ ប្រាង្គពីរទៀតត្រូវរលំបាក់បែកអស់។ តួប្រាង្គកណ្ដាលធំជាងគេ មានច្រកចូលពីខាងកើត និងទ្វារបញ្ឆោតធ្វើអំពីឥដ្ឋនៅទិសផ្សេងៗទៀត។ គេបានចាក់បំពេញដីក្នុងកំពែងទំហំ ៣០ម. បួនជ្រុងនោះកប់បាត់ជើងប្រាសាទ នៅសល់ត្រឹមមួយកំណាត់ទ្វារឡើងលើ។ មានការកែកុនជាច្រើន ដូចជាការសាងសង់រោងស៊ីម៉ង់មានដំបូលគ្របពីលើ ការសាងសង់សត្វតំណាងឆ្នាំទាំង ១២ នៅជុំវិញជាប់នឹងជញ្ជាំងប្រាសាទផងដែរ។ ប្រាង្គ ដែលនៅសល់តែ ១ សង់ពីឥដ្ឋ មានទំហំ ៤.៥ x ៥.៥ ម. កម្ពស់នៅសល់លើដី៧ ម.។ ចម្លាក់ផ្ដែរថ្មភក់នៅល្អស្អាត ជារូបព្រះឥន្ទជិះដំរី រចនាបថឃ្លាំងបាពួន ហើយបើពិនិត្យតាមសំណល់មានសសរពេជ្រសម័យមុនអង្គរនៃប្រាង្គពីរទៀត។ វត្តនេះក៏មានព្រះវិហារចំណាស់ផងដែរ។",
    "descriptionEn": "Kuk Ampil Tvea temple is surrounded by 2.5-meter-high laterite wall and the surround space of 30 m. x 30 m. Through the old records, this place is a temple complex with three towers built on the same platform, facing east, on the row from the north to the south. Unfortunately, the other two towers were collapsed. The biggest tower is the middle tower which the entrance is at the east, and the blind doors made of brick are at the other directions. The 30 meter of surround space wall was filled with soil which buried the platform of the temple, leaving only a portion of the door up. There are many improvements, such as the construction of a cement-hall with roof and the construction of the twelve animals which represent the years of birth around the temple walls. The remaining brick-tower is 4.5 X 4.5 m. size, and 7 m. high from the ground. The sandstone sculptures on the lintel are still in good condition, in the form of Indra riding on an elephant in the style of Khleang Baphuon. As notice the remains, there are colonettes of the other two towers in pre-Angkorian era. This pagoda also has an old Buddhist temple.",
